/**
 * api.js — where the Express backend lives.
 *
 * Local dev: leave REACT_APP_API_URL unset — relative paths go through the
 * CRA proxy (package.json "proxy") to http://localhost:3001.
 *
 * Production with the backend on its own host: build the frontend with
 *   REACT_APP_API_URL=https://your-backend.onrender.com
 */
export const API_BASE = (process.env.REACT_APP_API_URL || '').replace(/\/+$/, '');

/* Prefix a server path (/api/..., /suit-prototypes/..., /tryon-results/...) with the backend URL */
export const apiUrl = p => (!p || /^(https?:|data:|blob:)/.test(p) ? p : API_BASE + p);
