import React from 'react';
import '../styles/Sidebar.css';

/**
 * Sidebar.js — Navigation with Prototype Manager added
 */
const NAV_ITEMS = [
  { id: 'home',      label: 'Dashboard',          icon: '⊞', description: 'Overview & stats' },
  { id: 'tailor',   label: 'Virtual Tailor',      icon: '✂', description: 'Try on & capture' },
  { id: 'AIOutFitChange',  label: 'AI Mirror',           icon: '✨', description: 'See any blazer on you' },
  { id: 'protos',   label: 'Prototype Manager',   icon: '👔', description: 'Upload & manage suits' },
  { id: 'saved',    label: 'Saved Fits',           icon: '♡', description: 'My saved looks' },
  { id: 'orders',   label: 'Orders',              icon: '📦', description: 'Track my orders' }, 
];

function Sidebar({ activeModule, onNavigate, isOpen }) {
  return (
    <aside className={`sidebar ${isOpen ? 'open' : 'collapsed'}`} aria-label="Main navigation">
      <nav className="sidebar-nav">
        {NAV_ITEMS.map(item => (
          <button
            key={item.id}
            className={`nav-item ${activeModule === item.id ? 'active' : ''}`}
            onClick={() => onNavigate(item.id)}
            title={item.label}
            aria-current={activeModule === item.id ? 'page' : undefined}
          >
            <span className="nav-icon">{item.icon}</span>
            {isOpen && (
              <div className="nav-text">
                <span className="nav-label">{item.label}</span>
                <span className="nav-desc">{item.description}</span>
              </div>
            )}
            {isOpen && activeModule === item.id && (
              <span className="nav-active-indicator" />
            )}
          </button>
        ))}
      </nav>

      {isOpen && (
        <div className="sidebar-footer">
          <div className="upgrade-card">
            <span className="upgrade-icon">⚡</span>
            <div>
              <p className="upgrade-title">AI Pro Features</p>
              <p className="upgrade-desc">Real-time body scan</p>
            </div>
          </div>
          <button className="upgrade-btn">Upgrade Plan</button>
        </div>
      )}
    </aside>
  );
}

export default Sidebar;
