import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Footer from './components/Footer';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import './styles/App.css';

/**
 * App.js — Root component
 * Mobile: sidebar is a slide-over drawer, closed by default.
 * Desktop: sidebar is persistent, open by default.
 */
function App() {
  const [activeModule, setActiveModule] = useState('home');
  const [sidebarOpen, setSidebarOpen]   = useState(window.innerWidth >= 768);

  // Close sidebar on mobile when navigating
  const handleNavigate = (module) => {
    setActiveModule(module);
    if (window.innerWidth < 768) setSidebarOpen(false);
  };

  // On resize — auto-open sidebar when going desktop, close on mobile
  useEffect(() => {
    const onResize = () => {
      if (window.innerWidth >= 768) setSidebarOpen(true);
      else setSidebarOpen(false);
    };
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  return (
    <div className="app-shell">
      <Header
        sidebarOpen={sidebarOpen}
        onToggleSidebar={() => setSidebarOpen(prev => !prev)}
        activeModule={activeModule}
        onNavigate={handleNavigate}
      />

      <div className="app-body">
        {/* Backdrop overlay on mobile when sidebar open */}
        {sidebarOpen && (
          <div
            className="sidebar-backdrop"
            onClick={() => setSidebarOpen(false)}
            aria-hidden="true"
          />
        )}

        <Sidebar
          activeModule={activeModule}
          onNavigate={handleNavigate}
          isOpen={sidebarOpen}
          onClose={() => setSidebarOpen(false)}
        />

        <main className={`main-content ${sidebarOpen ? 'sidebar-open' : 'sidebar-closed'}`}>
          <Dashboard activeModule={activeModule} onNavigate={handleNavigate} />
        </main>
      </div>

      {/* Mobile bottom tab bar — replaces footer on small screens */}
      <Footer activeModule={activeModule} onNavigate={handleNavigate} />
    </div>
  );
}

export default App;
