/**
 * PrototypeStore.js  (v2 — API-backed, file-system storage)
 *
 * All prototype data is stored on the server:
 *   • Images  → public/suit-prototypes/<filename>.png  (served statically)
 *   • Metadata → public/suit-prototypes/manifest.json  (committed to repo)
 *
 * When you run `npm run build`, React copies everything in public/ into
 * the build/ folder, so the images and manifest are part of the deployment.
 *
 * API base: /api/prototypes  (proxied to Express on port 3001 in dev)
 */

import { apiUrl } from './api';

const API = apiUrl('/api/prototypes');

// Captured selfies are stored in the same manifest — they are not suits
const isSelfie = p => p.type === 'selfie' || String(p.id).startsWith('selfie_');

// Image paths from the server are relative to the backend host
const withAbsUrl = p => ({ ...p, imageUrl: apiUrl(p.imageUrl) });

/* ── GET all prototypes from server manifest ───────────────────── */
export async function getAllPrototypes() {
  try {
    const res = await fetch(API);
    if (!res.ok) throw new Error(`Failed to load prototypes: ${res.status}`);
    return (await res.json()).filter(p => !isSelfie(p)).map(withAbsUrl);
  } catch (err) {
    // If the API backend is unavailable, fall back to the static build manifest
    // bundled under public/suit-prototypes/manifest.json.
    try {
      const fallback = await fetch('/suit-prototypes/manifest.json');
      if (!fallback.ok) throw new Error(`Fallback manifest fetch failed: ${fallback.status}`);
      const data = await fallback.json();
      return Array.isArray(data.prototypes) ? data.prototypes.filter(p => !isSelfie(p)) : [];
    } catch (fallbackError) {
      throw new Error(err.message || fallbackError.message || 'Failed to load prototypes.');
    }
  }
}

/* ── GET saved selfies (newest first) ──────────────────────────── */
export async function getSelfies() {
  try {
    const res = await fetch(apiUrl('/api/selfies'));
    return res.ok ? (await res.json()).map(withAbsUrl) : [];
  } catch {
    return [];
  }
}

/* ── POST — upload image file + metadata ───────────────────────── */
export async function addPrototype(formData) {
  // formData is a native FormData with fields:
  //   image       — File object (PNG / JPG)
  //   name        — string
  //   description — string
  //   tags        — comma-separated string
  //   blazerColor — hex string
  //   tieColor    — hex string
  const res = await fetch(API, { method: 'POST', body: formData });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || `Upload failed: ${res.status}`);
  }
  return withAbsUrl(await res.json()); // the new prototype object including imageUrl
}

/* ── PUT — update metadata only (no new image) ─────────────────── */
export async function updatePrototype(id, fields) {
  // fields: { name, description, tags (comma string), blazerColor, tieColor }
  const res = await fetch(`${API}/${id}`, {
    method:  'PUT',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify(fields),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || `Update failed: ${res.status}`);
  }
  return withAbsUrl(await res.json());
}

/* ── DELETE — remove metadata and image file from server ───────── */
export async function deletePrototype(id) {
  const res = await fetch(`${API}/${id}`, { method: 'DELETE' });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || `Delete failed: ${res.status}`);
  }
  return res.json();
}
