import React, { useRef, useState, useEffect, useCallback } from 'react';
import { apiUrl } from '../utils/api';
import '../styles/CameraCapture.css';

/**
 * CameraCapture.js
 * Accesses the user's camera via MediaDevices API and captures a selfie.
 *
 * Props:
 *   onCapture(dataUrl: string) — called with Base64 PNG when photo is taken.
 *   capturedImage: string | null — already-captured image to show in review.
 */
function CameraCapture({ onCapture, capturedImage }) {
  const videoRef  = useRef(null);   // <video> element ref
  const canvasRef = useRef(null);   // Hidden <canvas> for snapshot
  const uploadInputRef = useRef(null);

  const [stream, setStream]         = useState(null);
  const [cameraActive, setCameraActive] = useState(false);
  const [error, setError]           = useState(null);
  const [facingMode, setFacingMode] = useState('user'); // 'user' = front cam

  /* ── Stop camera ───────────────────────────────────────────────── */
  const stopCamera = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    if (videoRef.current) videoRef.current.srcObject = null;
    setCameraActive(false);
  }, [stream]);

  /* ── Start camera ──────────────────────────────────────────────── */
  const startCamera = useCallback(async () => {
    // Release any existing stream first
    if (stream) stopCamera();

    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode, width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false,
      });

      setStream(mediaStream);
      setCameraActive(true);
      setError(null);
    } catch (err) {
      console.error('Camera access error:', err);
      if (err.name === 'NotAllowedError') {
        setError('Camera permission denied. Please allow access in your browser settings.');
      } else if (err.name === 'NotFoundError') {
        setError('No camera found on this device.');
      } else {
        setError(`Camera error: ${err.message}`);
      }
    }
  }, [facingMode, stream, stopCamera]);

  useEffect(() => {
    if (!cameraActive || !stream || !videoRef.current) return;
    const video = videoRef.current;

    if (video.srcObject !== stream) {
      video.srcObject = stream;
    }

    const handleLoadedMetadata = () => {
      const playPromise = video.play();
      if (playPromise && playPromise.catch) {
        playPromise.catch((playError) => {
          console.warn('Unable to autoplay camera preview:', playError);
        });
      }
    };

    video.addEventListener('loadedmetadata', handleLoadedMetadata);
    // Try play immediately too, in case metadata is already ready.
    handleLoadedMetadata();

    return () => {
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [cameraActive, stream]);

  /* ── Capture selfie from video frame ───────────────────────────── */
  const captureSelfie = useCallback(async () => {
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;
    if (video.videoWidth === 0 || video.videoHeight === 0) return;

    // Match canvas to video dimensions
    canvas.width  = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    ctx.save();

    // Mirror the image if using front camera (looks natural)
    if (facingMode === 'user') {
      ctx.translate(canvas.width, 0);
      ctx.scale(-1, 1);
    }

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    ctx.restore();

    const dataUrl = canvas.toDataURL('image/png');

    // Attempt to POST the captured selfie to the server so it is persisted
    // into public/suit-prototypes/. If the server is unavailable, fall
    // back to returning the data URL so the app still works offline.
    try {
      const res = await fetch(apiUrl('/api/selfies'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dataUrl }),
      });

      if (res.ok) {
        const json = await res.json();
        // The server returns the saved entry including imageUrl
        onCapture(apiUrl(json.imageUrl) || dataUrl);
      } else {
        onCapture(dataUrl);
      }
    } catch (err) {
      console.warn('Selfie upload failed, using local data URL', err);
      onCapture(dataUrl);
    }

    stopCamera();         // Turn off camera after capture
  }, [facingMode, onCapture, stopCamera]);

  /* ── Flip between front / rear camera ─────────────────────────── */
  const flipCamera = () => {
    setFacingMode(prev => (prev === 'user' ? 'environment' : 'user'));
  };

  /* ── Re-start when facingMode changes ─────────────────────────── */
  useEffect(() => {
    if (!cameraActive) return;
    startCamera();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [facingMode]);

  /* ── Cleanup on unmount ─────────────────────────────────────────── */
  useEffect(() => {
    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
    };
  }, [stream]);

  return (
    <div className="camera-capture">
      {/* ── Camera preview pane ──── */}
      {!capturedImage && (
        <div className="camera-pane">
          {cameraActive ? (
            <div className="video-wrapper">
              {/* Overlay guides */}
              <div className="face-guide">
                <div className="guide-oval" />
                <span className="guide-label">Center your face here</span>
              </div>

              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                className={`camera-video ${facingMode === 'user' ? 'mirrored' : ''}`}
              />

              {/* Camera controls */}
              <div className="camera-controls">
                <button className="ctrl-btn secondary" onClick={stopCamera} title="Stop camera">
                  ✕ Cancel
                </button>
                <button className="ctrl-btn capture" onClick={captureSelfie} title="Take selfie">
                  <span className="shutter-ring"><span className="shutter-dot" /></span>
                  Capture
                </button>
                <button className="ctrl-btn secondary" onClick={flipCamera} title="Flip camera">
                  ⟳ Flip
                </button>
              </div>
            </div>
          ) : (
            <div className="camera-placeholder">
              {error ? (
                <div className="camera-error">
                  <span className="error-icon">⚠</span>
                  <p>{error}</p>
                  <button className="ctrl-btn primary" onClick={startCamera}>
                    Try Again
                  </button>
                </div>
              ) : (
                <div className="camera-invite">
                  <div className="cam-icon-wrap">
                    <span className="cam-icon">📷</span>
                  </div>
                  <h3>Take Your Selfie</h3>
                  <p>We'll use your photo to overlay blazer and tie sets for a virtual try-on experience.</p>
                  <button className="ctrl-btn primary" onClick={startCamera}>
                    Open Camera
                  </button>
                  <button
                    className="ctrl-btn secondary"
                    onClick={() => uploadInputRef.current?.click()}
                  >
                    Upload Image
                  </button>
                  <span className="privacy-note">🔒 Photo stays on your device only</span>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* ── Captured image review ─── */}
      {capturedImage && (
        <div className="capture-review">
          <div className="review-header">
            <span className="review-badge">✓ Photo Captured</span>
          </div>
          <div className="review-image-wrap">
            <img src={capturedImage} alt="Your selfie" className="review-image" />
            <div className="scan-overlay">
              <div className="scan-beam" />
            </div>
          </div>
          <button
            className="ctrl-btn secondary retake-btn"
            onClick={() => { onCapture(null); startCamera(); }}
          >
            ↩ Retake Photo
          </button>
        </div>
      )}

      {/* Hidden canvas for snapshot capture */}
      <canvas ref={canvasRef} style={{ display: 'none' }} />

      {/* Hidden upload input for selecting existing images */}
      <input
        ref={uploadInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp"
        style={{ display: 'none' }}
        onChange={async (e) => {
          const f = e.target.files && e.target.files[0];
          if (!f) return;
          const reader = new FileReader();
          reader.onload = async () => {
            const dataUrl = reader.result;
            if (!dataUrl) return;
            try {
              const res = await fetch(apiUrl('/api/selfies'), {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ dataUrl }),
              });
              if (res.ok) {
                const json = await res.json();
                onCapture(apiUrl(json.imageUrl) || dataUrl);
              } else {
                onCapture(dataUrl);
              }
            } catch (err) {
              console.warn('Upload failed, using local data URL', err);
              onCapture(dataUrl);
            }
          };
          reader.readAsDataURL(f);
        }}
      />
    </div>
  );
}

export default CameraCapture;
