import React, { useState, useCallback, useEffect } from 'react';
import CameraCapture from './CameraCapture';
import DressCarousel from './DressCarousel';
import MeasurementProcessor from './MeasurementProcessor';
import { getAllPrototypes } from '../utils/PrototypeStore';
import { apiUrl } from '../utils/api';
import '../styles/VirtualTailor.css';

/**
 * VirtualTailor.js
 *
 * FLOW:
 *   Step 0 — Browse uploaded prototype images
 *   Step 1 — Capture selfie via camera
 *   Step 2 — Try On: AI Fitting Mirror (generative composite via /api/tryon/generate)
 *            + DressCarousel fallback preview (proportional canvas overlay,
 *            pose-based scale/taper — useful if the AI endpoint errors out
 *            or isn't configured, and doubles as the suit picker strip)
 *   Step 3 — AI body measurement analysis (pose-detection based)
 *   Step 4 — Submit order + measurements to Express backend
 */

const STEPS = [
  { id: 0, label: 'Browse',   icon: '👔' },
  { id: 1, label: 'Capture',  icon: '📷' },
  { id: 2, label: 'Try On',   icon: '✂'  },
  { id: 3, label: 'Measure',  icon: '◎'  },
  { id: 4, label: 'Submit',   icon: '📦' },
];

function VirtualTailor({ onNavigate }) {
  const [currentStep,  setCurrentStep]  = useState(0);
  const [selfieImage,  setSelfieImage]  = useState(null); // Base64 or URL
  const [selectedSet,  setSelectedSet]  = useState(null);
  const [measurements, setMeasurements] = useState(null);
  const [submitStatus, setSubmitStatus] = useState('idle'); // idle | loading | success | error
  const [orderRef,     setOrderRef]     = useState(null);
  const [prototypes,   setPrototypes]   = useState([]);

  // AI Try-On Generation States
  const [tryOnResult,  setTryOnResult]  = useState(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [errorMsg,     setErrorMsg]     = useState(null);

  // Load prototypes from server on mount
  useEffect(() => {
    getAllPrototypes()
      .then(setPrototypes)
      .catch(() => setPrototypes([]));
  }, []);

  // Trigger the Deep Learning AI Generation via backend
  const handleGenerateTryOn = async () => {
    if (!selfieImage || !selectedSet) return;

    setIsGenerating(true);
    setErrorMsg(null);
    setTryOnResult(null);

    try {
      const response = await fetch(apiUrl('/api/tryon/generate'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          humanImage: selfieImage,             // The user selfie
          garmentImage: selectedSet.imageUrl,  // The selected suit image
          category: 'upper_body',              // upper_body, lower_body, or dresses
        }),
      });

      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || data.error || `AI generation failed (server ${response.status}). Is "npm run server" running?`);
      }

      if (data.success && data.outputUrl) {
        setTryOnResult(apiUrl(data.outputUrl));
      } else {
        throw new Error(data.message || 'Failed to generate image layer.');
      }
    } catch (err) {
      console.error(err);
      setErrorMsg(err.message);
    } finally {
      setIsGenerating(false);
    }
  };

  // Run generation automatically when step 2 is active and assets are ready
  useEffect(() => {
    if (currentStep === 2 && selfieImage && selectedSet && !tryOnResult && !isGenerating) {
      handleGenerateTryOn();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentStep, selfieImage, selectedSet]);

  // Step 0: user picks a prototype from the browse grid
  const handlePreviewSelect = useCallback((proto) => {
    setSelectedSet(proto);
  }, []);

  const handleProceedToCapture = useCallback(() => {
    setCurrentStep(1);
  }, []);

  // Step 1: selfie captured
  const handleCapture = useCallback((dataUrl) => {
    setSelfieImage(dataUrl);
    setTryOnResult(null); // clear old AI render, a new selfie needs a new composite
    setErrorMsg(null);
    if (dataUrl) setCurrentStep(2);
    else         setCurrentStep(1);
  }, []);

  // Step 2: different prototype selected in carousel
  const handleSelectSet = useCallback((proto) => {
    setSelectedSet(proto);
    setTryOnResult(null); // re-trigger AI generation for the newly picked suit
    setErrorMsg(null);
    if (measurements) setCurrentStep(4);
    else              setCurrentStep(3);
  }, [measurements]);

  // Step 3: measurements ready from AI processor
  const handleMeasurements = useCallback((data) => {
    setMeasurements(data);
    if (selectedSet) setCurrentStep(4);
  }, [selectedSet]);

  // Step 4: submit order to Express backend
  const handleSubmitOrder = async () => {
    if (!selfieImage || !selectedSet || !measurements) return;
    setSubmitStatus('loading');

    const payload = {
      selfie:        selfieImage,
      tryOnResult:   tryOnResult || null, // AI-generated composite, if one was produced
      prototypeId:   selectedSet.id,
      prototypeName: selectedSet.name,
      measurements: {
        neckSize:         measurements.neckSize,
        shoulderWidth:    measurements.shoulderWidth,
        chestCirc:        measurements.chestCirc,
        waistCirc:        measurements.waistCirc,
        sleeveLength:     measurements.sleeveLength,
        torsoLength:      measurements.torsoLength,
        heightCm:         measurements.heightCm,
        bodyProfile:      measurements.bodyProfile,
        broadShoulder:    measurements.broadShoulder,
        slimFit:          measurements.slimFit,
        skinTone:         measurements.skinTone,
        estimationMethod: measurements.estimationMethod, // 'pose' | 'simulated' — lets the tailor know confidence
      },
      submittedAt: new Date().toISOString(),
    };

    try {
      const res = await fetch(apiUrl('/api/orders/submit'), {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify(payload),
      });
      if (!res.ok) throw new Error(`Server ${res.status}`);
      const result = await res.json();
      setOrderRef(result.orderId || `TL-${Date.now().toString().slice(-4)}`);
      setSubmitStatus('success');
    } catch (err) {
      // Demo fallback: simulate success when no backend is running
      if (!err.message.includes('Server')) {
        await new Promise(r => setTimeout(r, 1400));
        setOrderRef(`TL-${Date.now().toString().slice(-4)}`);
        setSubmitStatus('success');
      } else {
        setSubmitStatus('error');
      }
    }
  };

  const handleReset = () => {
    setSelfieImage(null);
    setSelectedSet(null);
    setMeasurements(null);
    setTryOnResult(null);
    setIsGenerating(false);
    setErrorMsg(null);
    setSubmitStatus('idle');
    setOrderRef(null);
    setCurrentStep(0);
    getAllPrototypes().then(setPrototypes).catch(() => {});
  };

  const stepDone = {
    0: !!selectedSet,
    1: !!selfieImage,
    2: !!selectedSet && !!selfieImage,
    3: !!measurements,
    4: submitStatus === 'success',
  };

  return (
    <div className="virtual-tailor">

      {/* Module header */}
      <div className="vt-header">
        <h1>Virtual Tailor <span className="vt-ai-badge">AI</span></h1>
        <p>Browse your suit prototypes → Capture selfie → Try on → Get measured → Order</p>
      </div>

      {/* Step progress */}
      <div className="vt-steps">
        {STEPS.map((step, idx) => (
          <React.Fragment key={step.id}>
            <div className={`step-node ${currentStep === step.id ? 'active' : ''} ${stepDone[step.id] ? 'done' : ''}`}>
              <span className="step-icon">{stepDone[step.id] ? '✓' : step.icon}</span>
              <span className="step-label">{step.label}</span>
            </div>
            {idx < STEPS.length - 1 && (
              <div className={`step-connector ${stepDone[step.id] ? 'done' : ''}`} />
            )}
          </React.Fragment>
        ))}
      </div>

      {/* ════ STEP 0 — Browse uploaded prototypes ════ */}
      {currentStep === 0 && (
        <div className="vt-section visible">
          <div className="section-tag">Step 1 — Pick a Suit Prototype</div>

          {prototypes.length === 0 ? (
            <div className="vt-no-protos">
              <span className="vt-no-protos-icon">👔</span>
              <h3>No suit prototypes uploaded yet</h3>
              <p>
                Go to <strong>Prototype Manager</strong> to upload your transparent
                PNG or JPG suit images. They'll appear here for customers to try on.
              </p>
              {onNavigate && (
                <button className="cta-btn" onClick={() => onNavigate('protos')}>
                  Open Prototype Manager ✦
                </button>
              )}
            </div>
          ) : (
            <>
              <p className="browse-sub">
                Select a suit to try on. You can also change it after taking your selfie.
              </p>

              <div className="prototype-grid">
                {prototypes.map(proto => (
                  <button
                    key={proto.id}
                    className={`proto-card ${selectedSet?.id === proto.id ? 'selected' : ''}`}
                    onClick={() => handlePreviewSelect(proto)}
                  >
                    <div className="proto-preview">
                      <div className="proto-checker" />
                      <img
                        src={proto.imageUrl}
                        alt={proto.name}
                        className="proto-img"
                      />
                      {selectedSet?.id === proto.id && (
                        <div className="proto-selected-badge">✓ Selected</div>
                      )}
                    </div>

                    <div className="proto-info">
                      <span className="proto-name">{proto.name}</span>
                      {proto.description && (
                        <span className="proto-desc">{proto.description}</span>
                      )}
                      {proto.tags && proto.tags.length > 0 && (
                        <div className="proto-tags">
                          {proto.tags.slice(0, 3).map(t => (
                            <span key={t} className="proto-tag">{t}</span>
                          ))}
                        </div>
                      )}
                      <div className="proto-swatches">
                        <span className="swatch-wrap">
                          <span className="swatch-dot" style={{ background: proto.blazerColor }} />
                          <span className="swatch-label">Blazer</span>
                        </span>
                        <span className="swatch-wrap">
                          <span className="swatch-dot" style={{ background: proto.tieColor }} />
                          <span className="swatch-label">Tie</span>
                        </span>
                      </div>
                    </div>
                  </button>
                ))}
              </div>

              <div className="browse-footer">
                {selectedSet ? (
                  <div className="browse-selection-bar">
                    <div className="browse-sel-info">
                      <img
                        src={selectedSet.imageUrl}
                        alt={selectedSet.name}
                        className="browse-sel-thumb"
                      />
                      <div>
                        <span className="browse-sel-name">{selectedSet.name}</span>
                        {selectedSet.description && (
                          <span className="browse-sel-desc">{selectedSet.description}</span>
                        )}
                      </div>
                    </div>
                    <button className="cta-btn" onClick={handleProceedToCapture}>
                      Take Selfie to Try This On ✦
                    </button>
                  </div>
                ) : (
                  <p className="browse-prompt">← Select any suit above to continue</p>
                )}
              </div>
            </>
          )}
        </div>
      )}

      {/* ════ STEPS 1–4 — Capture, Try On, Measure, Submit ════ */}
      {currentStep >= 1 && submitStatus !== 'success' && (
        <div className="vt-workspace" style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>

          {/* Left column */}
          <div className="vt-left" style={{ flex: '1 1 420px' }}>
            <div className="vt-section visible">
              <div className="section-tag">Step 2 — Take Selfie</div>
              <CameraCapture onCapture={handleCapture} capturedImage={selfieImage} />
            </div>

            {/* Selected suit reminder before selfie */}
            {selectedSet && !selfieImage && (
              <div className="set-reminder">
                <div className="reminder-checker" />
                <img
                  src={selectedSet.imageUrl}
                  alt={selectedSet.name}
                  className="reminder-img"
                />
                <div className="reminder-info">
                  <span className="reminder-label">Selected suit</span>
                  <span className="reminder-name">{selectedSet.name}</span>
                  {selectedSet.description && (
                    <span className="reminder-desc">{selectedSet.description}</span>
                  )}
                  <button className="reminder-change" onClick={() => setCurrentStep(0)}>
                    ← Change suit
                  </button>
                </div>
              </div>
            )}

            {/* AI Fitting Mirror — generative try-on composite */}
            {selfieImage && selectedSet && (
              <div
                className="vt-section visible AI-tryon-container"
                style={{ marginTop: '20px', padding: '15px', background: '#fff', borderRadius: '8px', border: '1px solid #ddd' }}
              >
                <div className="section-tag">Step 3 — AI Fitting Mirror</div>

                <div
                  style={{
                    position: 'relative', width: '100%', aspectRatio: '3/4',
                    backgroundColor: '#eaeaea', borderRadius: '6px', overflow: 'hidden',
                    display: 'flex', justifyContent: 'center', alignItems: 'center',
                  }}
                >
                  {isGenerating && (
                    <div
                      style={{
                        position: 'absolute', zIndex: 10, textAlign: 'center',
                        background: 'rgba(255,255,255,0.85)', width: '100%', height: '100%',
                        display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center',
                      }}
                    >
                      <div
                        className="spinner"
                        style={{ border: '4px solid #f3f3f3', borderTop: '4px solid #3498db', borderRadius: '50%', width: '40px', height: '40px', animation: 'spin 1s linear infinite' }}
                      />
                      <p style={{ marginTop: '10px', fontWeight: 'bold' }}>AI is stitching the garment onto your photo...</p>
                      <p style={{ fontSize: '12px', color: '#666' }}>Usually takes 20–60 seconds</p>
                    </div>
                  )}

                  {errorMsg && (
                    <div style={{ color: 'red', padding: '20px', textAlign: 'center' }}>
                      <p>⚠️ {errorMsg}</p>
                      <p style={{ fontSize: '12px', color: '#888' }}>
                        Showing the proportional preview below instead.
                      </p>
                      <button onClick={handleGenerateTryOn} style={{ marginTop: '10px', padding: '6px 12px' }}>
                        Retry AI Generation
                      </button>
                    </div>
                  )}

                  {tryOnResult ? (
                    <img
                      src={tryOnResult}
                      alt="AI Virtual Try On Result"
                      style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                    />
                  ) : (
                    !isGenerating && !errorMsg && <p style={{ color: '#888' }}>Awaiting pipeline execution stream...</p>
                  )}
                </div>

                <div style={{ marginTop: '10px', textAlign: 'right' }}>
                  <button onClick={handleGenerateTryOn} disabled={isGenerating} style={{ padding: '6px 12px', cursor: 'pointer' }}>
                    🔄 Re-generate Fit
                  </button>
                </div>
              </div>
            )}

            {/* Fallback / picker: proportional canvas overlay + suit carousel */}
            {selfieImage && (
              <div className="vt-section visible" style={{ marginTop: '20px' }}>
                <div className="section-tag">Fallback Preview &amp; Suit Picker</div>
                <DressCarousel
                  selfieImage={selfieImage}
                  selectedSet={selectedSet}
                  onSelectSet={handleSelectSet}
                  measurements={measurements}
                />
              </div>
            )}
          </div>

          {/* Right column */}
          <div className="vt-right" style={{ flex: '1 1 340px' }}>

            {/* Step 3 — AI Measurements */}
            {selfieImage && (
              <div className="vt-section visible">
                <div className="section-tag">Step 4 — Body Analysis</div>
                <MeasurementProcessor
                  selfieImage={selfieImage}
                  onMeasurements={handleMeasurements}
                />
              </div>
            )}

            {/* Step 4 — Order summary + submit */}
            {measurements && selectedSet && (
              <div className="vt-section visible order-section">
                <div className="section-tag">Step 5 — Place Order</div>
                <div className="order-summary">
                  <div className="order-summary-header">
                    <div className="order-thumb-wrap">
                      <div className="order-thumb-checker" />
                      <img
                        src={tryOnResult || selectedSet.imageUrl}
                        alt={selectedSet.name}
                        className="order-proto-thumb"
                      />
                    </div>
                    <div>
                      <h3>{selectedSet.name}</h3>
                      {selectedSet.description && (
                        <span className="order-proto-desc">{selectedSet.description}</span>
                      )}
                    </div>
                  </div>

                  {measurements.estimationMethod === 'simulated' && (
                    <p style={{ background: '#fff4e5', padding: '8px 10px', borderRadius: '6px', fontSize: '13px', margin: '10px 0' }}>
                      ⚠ These measurements are an approximation — a full-body pose wasn't
                      detected in your photo. You can still order, but consider retaking
                      the selfie for a more accurate fit.
                    </p>
                  )}

                  <div className="summary-rows">
                    {[
                      ['Build',    measurements.bodyProfileLabel],
                      ['Neck',     `${measurements.neckSize} cm`],
                      ['Chest',    `${measurements.chestCirc} cm`],
                      ['Shoulder', `${measurements.shoulderWidth} cm`],
                      ['Sleeve',   `${measurements.sleeveLength} cm`],
                      ['Torso',    `${measurements.torsoLength} cm`],
                      ['Cut',      measurements.broadShoulder ? 'Broad shoulder' : measurements.slimFit ? 'Slim fit' : 'Regular'],
                    ].map(([k, v]) => (
                      <div className="summary-row" key={k}>
                        <span className="sk">{k}</span>
                        <span>{v}</span>
                      </div>
                    ))}
                  </div>

                  <button
                    className={`submit-btn ${submitStatus === 'loading' ? 'loading' : ''}`}
                    onClick={handleSubmitOrder}
                    disabled={submitStatus === 'loading'}
                  >
                    {submitStatus === 'loading'
                      ? <><span className="spinner" /> Placing order…</>
                      : '📦 Submit Order to Tailor'}
                  </button>

                  {submitStatus === 'error' && (
                    <p className="submit-error">⚠ Could not reach server. Try again.</p>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ════ Success screen ════ */}
      {submitStatus === 'success' && (
        <div className="vt-section visible success-section">
          <div className="success-card">
            <div className="success-thumb-wrap">
              <div className="success-thumb-checker" />
              <img
                src={tryOnResult || selectedSet.imageUrl}
                alt={selectedSet.name}
                className="success-proto-img"
              />
            </div>
            <div className="success-content">
              <div className="success-icon-wrap">
                <span className="success-icon">✓</span>
              </div>
              <h2>Order Placed!</h2>
              <p>
                Your measurements and <strong>{selectedSet.name}</strong> selection
                have been sent to our tailor.
              </p>
              <div className="order-ref">
                Order reference: <strong>{orderRef}</strong>
              </div>
              <p className="success-sub">
                Stitching begins within 24 hours. Email updates at every stage.
              </p>
              <button className="cta-btn" onClick={handleReset}>
                Start New Try-On ✦
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default VirtualTailor;