import React, { useState, useEffect, useRef, useCallback } from 'react';
import { getAllPrototypes, getSelfies } from '../utils/PrototypeStore';
import { FABRIC_TYPES, FABRIC_COLORS, renderFabric } from '../utils/fabricRecolor';
import { apiUrl } from '../utils/api';
import '../styles/AIOutfitChanger.css';

/**
 * AIOutfitChanger.js — "AI Mirror" virtual blazer try-on
 *
 *   1. Upload a photo (or camera / saved selfie)
 *   2. Choose a blazer from the prototype library (or upload one)
 *   3. Choose a fabric type and colour
 *   4. Apply → the server's free AI models dress the customer in the blazer
 *      (painted chroma-key green), then the browser paints the chosen fabric
 *   5. Output — before/after slider, download, fabric changes re-apply instantly
 *
 * Only step 4's first run per (photo, blazer) uses the AI; it is cached on the
 * server too, so the free daily quota goes much further.
 */

const MODEL_W = 768;
const MODEL_H = 1024;

const STATUS_STEPS = [
  'Detecting body pose…',
  'Mapping shoulders & torso…',
  'Draping the blazer…',
  'Matching fabric & lighting…',
  'Finishing details…',
];

/* Fit any photo to the model's 768×1024 portrait: centre-crop wide photos,
   pad tall ones with their own background colour */
function normalizePhoto(source) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous'; // saved selfies come from the backend host
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = MODEL_W;
      canvas.height = MODEL_H;
      const ctx = canvas.getContext('2d');
      const aspect = img.width / img.height;
      if (aspect > MODEL_W / MODEL_H) {
        const sw = img.height * MODEL_W / MODEL_H;
        ctx.drawImage(img, (img.width - sw) / 2, 0, sw, img.height, 0, 0, MODEL_W, MODEL_H);
      } else {
        ctx.drawImage(img, 0, 0, 1, 1, 0, 0, MODEL_W, MODEL_H); // background from the top-left pixel
        const dw = MODEL_H * aspect;
        ctx.drawImage(img, (MODEL_W - dw) / 2, 0, dw, MODEL_H);
      }
      canvas.toBlob(blob => {
        if (!blob) return reject(new Error('Could not read this image.'));
        resolve({ blob, url: URL.createObjectURL(blob), id: `photo_${Date.now()}` });
      }, 'image/jpeg', 0.92);
    };
    img.onerror = () => reject(new Error('Could not read this image.'));
    img.src = typeof source === 'string' ? source : URL.createObjectURL(source);
  });
}

export default function AIOutfitChanger({ onNavigate }) {
  const [photo, setPhoto]             = useState(null);   // { blob, url, id }
  const [suits, setSuits]             = useState([]);
  const [selfies, setSelfies]         = useState([]);
  const [customGarment, setCustom]    = useState(null);   // { file, url, key }
  const [selectedKey, setSelectedKey] = useState(null);
  const [fabric, setFabric]           = useState('plain');
  const [colorId, setColorId]         = useState('original');
  const [customHex, setCustomHex]     = useState('#8a2be2');
  const [bases, setBases]             = useState({});     // `${photoId}:${key}` → server result
  const [look, setLook]               = useState(null);   // { url, baseId, label }
  const [looks, setLooks]             = useState([]);
  const [loading, setLoading]         = useState(false);
  const [painting, setPainting]       = useState(false);
  const [elapsed, setElapsed]         = useState(0);
  const [error, setError]             = useState(null);
  const [split, setSplit]             = useState(100);    // % of the result shown
  const [cameraOn, setCameraOn]       = useState(false);

  const videoRef    = useRef(null);
  const streamRef   = useRef(null);
  const stageRef    = useRef(null);
  const draggingRef = useRef(false);

  useEffect(() => {
    getAllPrototypes().then(setSuits).catch(err => setError(err.message));
    getSelfies().then(setSelfies);
  }, []);

  /* Elapsed timer while the AI runs */
  useEffect(() => {
    if (!loading) return undefined;
    setElapsed(0);
    const t = setInterval(() => setElapsed(e => e + 1), 1000);
    return () => clearInterval(t);
  }, [loading]);

  useEffect(() => () => stopCamera(), []);

  const baseId = photo && selectedKey ? `${photo.id}:${selectedKey}` : null;
  const base = baseId ? bases[baseId] : null;
  const colorHex = colorId === 'custom'
    ? customHex
    : colorId === 'original'
      ? (base && base.garment_color) || '#1c1c1f'
      : FABRIC_COLORS.find(c => c.id === colorId).hex;
  const garmentName = selectedKey === customGarment?.key
    ? 'Your blazer'
    : suits.find(s => s.id === selectedKey)?.name;
  const fabricLabel = `${colorId === 'custom' ? 'Custom colour' : FABRIC_COLORS.find(c => c.id === colorId).label} · ${FABRIC_TYPES.find(f => f.id === fabric).label}`;
  const showingLook = look && look.baseId === baseId;

  /* ── Photo input ─────────────────────────────────────────────── */
  const loadPhoto = async source => {
    try {
      setError(null);
      setPhoto(await normalizePhoto(source));
      setLook(null);
      setSplit(100);
    } catch (err) {
      setError(err.message);
    }
  };

  const startCamera = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 960 }, height: { ideal: 1280 } },
      });
      streamRef.current = stream;
      setCameraOn(true);
      requestAnimationFrame(() => { if (videoRef.current) videoRef.current.srcObject = stream; });
    } catch {
      setError('Camera not available. Please upload a photo instead.');
    }
  };

  function stopCamera() {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    streamRef.current = null;
    setCameraOn(false);
  }

  const snapPhoto = () => {
    const v = videoRef.current;
    if (!v || !v.videoWidth) return;
    const canvas = document.createElement('canvas');
    canvas.width = v.videoWidth;
    canvas.height = v.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.translate(canvas.width, 0); // mirror, like a real mirror
    ctx.scale(-1, 1);
    ctx.drawImage(v, 0, 0);
    stopCamera();
    loadPhoto(canvas.toDataURL('image/jpeg', 0.92));
  };

  /* ── Step 4: Apply ───────────────────────────────────────────── */
  const paint = useCallback(async (result, id, hex, label) => {
    setPainting(true);
    try {
      const url = await renderFabric({ resultUrl: result.output_url, color: hex, fabric });
      setLook({ url, baseId: id, label });
      setLooks(prev => [{ url, baseId: id, label, at: Date.now() }, ...prev.filter(l => l.label !== label || l.baseId !== id)].slice(0, 12));
    } catch (err) {
      setError(err.message);
    } finally {
      setPainting(false);
    }
  }, [fabric]);

  const apply = async () => {
    if (!photo) return setError('Step 1: upload or take a photo first.');
    if (!selectedKey) return setError('Step 2: choose a blazer.');
    setError(null);
    setSplit(100);
    const label = `${garmentName} — ${fabricLabel}`;

    let result = base;
    if (!result) {
      setLoading(true);
      const form = new FormData();
      form.append('person', photo.blob, 'person.jpg');
      form.append('keyed', 'true');
      if (selectedKey === customGarment?.key) form.append('garment', customGarment.file);
      else form.append('prototypeId', selectedKey);
      try {
        const res  = await fetch(apiUrl('/api/tryon'), { method: 'POST', body: form });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) {
          // A bare 500/504 comes from the dev proxy when the backend isn't running
          throw new Error(data.error || ([500, 502, 504].includes(res.status)
            ? 'Cannot reach the AI server. Start it with "npm run server" (or use "npm run dev").'
            : `Server responded with ${res.status}`));
        }
        result = { ...data, output_url: apiUrl(data.output_url) };
        setBases(b => ({ ...b, [baseId]: result }));
      } catch (err) {
        setError(err.message === 'Failed to fetch'
          ? 'Cannot reach the server. Start it with "npm run server".'
          : err.message);
        return;
      } finally {
        setLoading(false);
      }
    }
    const hex = colorId === 'original' ? result.garment_color || '#1c1c1f' : colorHex;
    await paint(result, baseId, hex, label);
  };

  /* After the first AI fit, fabric changes re-apply instantly (no AI call) */
  useEffect(() => {
    if (showingLook && base && !loading) paint(base, baseId, colorHex, `${garmentName} — ${fabricLabel}`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fabric, colorId, customHex]);

  const onCustomGarment = file => {
    if (!file) return;
    const g = { file, url: URL.createObjectURL(file), key: `custom_${Date.now()}` };
    setCustom(g);
    setSelectedKey(g.key);
  };

  /* ── Before / after slider ──────────────────────────────────── */
  const moveSplit = clientX => {
    const rect = stageRef.current.getBoundingClientRect();
    setSplit(Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100)));
  };
  const onPointerDown = e => {
    if (!showingLook) return;
    draggingRef.current = true;
    e.currentTarget.setPointerCapture(e.pointerId);
    moveSplit(e.clientX);
  };
  const onPointerMove = e => { if (draggingRef.current) moveSplit(e.clientX); };
  const onPointerUp   = () => { draggingRef.current = false; };

  const hasAiFit = !!base;
  const busy = loading || painting;

  return (
    <div className="mirror">
      <div className="module-header">
        <h1>AI Mirror</h1>
        <p>Upload your photo, pick a blazer and fabric, and see yourself wearing it.</p>
      </div>

      <div className="mirror-layout">
        {/* ── Stage: step 1 (photo) and step 5 (output) ─────────── */}
        <section className="mirror-stage-wrap">
          <div
            ref={stageRef}
            className={`mirror-stage ${showingLook ? 'has-result' : ''}`}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
          >
            {cameraOn ? (
              <>
                <video ref={videoRef} className="mirror-video" autoPlay playsInline muted />
                <div className="mirror-guide" />
                <div className="mirror-cam-actions">
                  <button className="mirror-btn ghost" onClick={stopCamera}>Cancel</button>
                  <button className="mirror-shutter" onClick={snapPhoto} aria-label="Take photo" />
                </div>
              </>
            ) : photo ? (
              <>
                <img className="mirror-img" src={photo.url} alt="You" draggable={false} />
                {showingLook && (
                  <>
                    <img
                      key={look.url}
                      className="mirror-img mirror-result"
                      src={look.url}
                      alt={`You wearing ${look.label}`}
                      draggable={false}
                      style={{ clipPath: `inset(0 ${100 - split}% 0 0)` }}
                    />
                    {split < 100 && (
                      <div className="mirror-divider" style={{ left: `${split}%` }}>
                        <span className="mirror-handle">⇆</span>
                      </div>
                    )}
                    <span className="mirror-tag after">After</span>
                    <span className="mirror-tag before">Before</span>
                    <span className="mirror-caption">{look.label}</span>
                  </>
                )}
                {loading && (
                  <div className="mirror-loading">
                    <div className="mirror-scanline" />
                    <div className="mirror-loading-card">
                      <div className="mirror-spinner" />
                      <strong>{STATUS_STEPS[Math.min(STATUS_STEPS.length - 1, Math.floor(elapsed / 7))]}</strong>
                      <span>{elapsed}s · first fit usually takes 25–60s</span>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <div className="mirror-empty">
                <span className="mirror-step-badge">1</span>
                <h3>Add your photo</h3>
                <p>A front-facing, waist-up photo with arms relaxed works best.</p>
                <div className="mirror-empty-actions">
                  <label className="mirror-btn primary">
                    Upload photo
                    <input type="file" accept="image/*" hidden onChange={e => e.target.files[0] && loadPhoto(e.target.files[0])} />
                  </label>
                  <button className="mirror-btn ghost" onClick={startCamera}>Use camera</button>
                </div>
                {selfies.length > 0 && (
                  <div className="mirror-selfies">
                    <span>Or use a saved selfie</span>
                    <div className="mirror-selfies-row">
                      {selfies.slice(0, 6).map(s => (
                        <button key={s.id} className="mirror-selfie" onClick={() => loadPhoto(s.imageUrl)} title={s.name}>
                          <img src={s.imageUrl} alt={s.name} />
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {photo && !cameraOn && (
            <div className="mirror-toolbar">
              <label className="mirror-btn ghost">
                Change photo
                <input type="file" accept="image/*" hidden onChange={e => e.target.files[0] && loadPhoto(e.target.files[0])} />
              </label>
              <button className="mirror-btn ghost" onClick={startCamera}>Retake</button>
              {showingLook && (
                <>
                  <button className="mirror-btn ghost" onClick={() => setSplit(split < 100 ? 100 : 50)}>
                    {split < 100 ? 'Hide compare' : 'Compare'}
                  </button>
                  <a className="mirror-btn ghost" href={look.url} download={`tailorai-look-${Date.now()}.jpg`}>
                    Download
                  </a>
                  {onNavigate && (
                    <button className="mirror-btn primary" onClick={() => onNavigate('tailor')}>
                      Get it tailored ✦
                    </button>
                  )}
                </>
              )}
            </div>
          )}

          {error && <p className="mirror-error">{error}</p>}

          {looks.length > 1 && (
            <div className="mirror-history">
              <h2 className="mirror-rail-title">Your looks</h2>
              <div className="mirror-looks">
                {looks.map(l => (
                  <button
                    key={l.at}
                    className={`mirror-look ${look && look.url === l.url ? 'active' : ''}`}
                    onClick={() => { setLook(l); setSplit(100); }}
                    title={l.label}
                  >
                    <img src={l.url} alt={l.label} />
                  </button>
                ))}
              </div>
            </div>
          )}
        </section>

        {/* ── Rail: steps 2–4 ─────────────────────────────────── */}
        <aside className="mirror-rail">
          <h2 className="mirror-rail-title"><span className="mirror-step-badge sm">2</span> Choose a blazer</h2>
          <div className="mirror-suits">
            {suits.map(s => (
              <button
                key={s.id}
                className={`mirror-suit ${selectedKey === s.id ? 'active' : ''}`}
                onClick={() => setSelectedKey(s.id)}
                disabled={loading}
                title={s.name}
              >
                <img src={s.imageUrl} alt={s.name} />
                <span className="mirror-suit-name">{s.name}</span>
                {photo && bases[`${photo.id}:${s.id}`] && <span className="mirror-suit-badge" title="AI fit ready">✓</span>}
              </button>
            ))}
            <label className={`mirror-suit upload ${customGarment && selectedKey === customGarment.key ? 'active' : ''} ${loading ? 'disabled' : ''}`}>
              {customGarment
                ? <img src={customGarment.url} alt="Your blazer" />
                : <span className="mirror-upload-plus">＋</span>}
              <span className="mirror-suit-name">{customGarment ? 'Your blazer' : 'Upload a blazer'}</span>
              <input
                type="file"
                accept="image/*"
                hidden
                disabled={loading}
                onChange={e => { onCustomGarment(e.target.files[0]); e.target.value = ''; }}
              />
            </label>
          </div>
          {suits.length === 0 && (
            <p className="mirror-rail-hint">
              No blazers yet. Add some in the <button className="mirror-link" onClick={() => onNavigate && onNavigate('protos')}>Prototype Manager</button>.
            </p>
          )}

          <h2 className="mirror-rail-title"><span className="mirror-step-badge sm">3</span> Choose fabric</h2>
          <div className="mirror-fabrics">
            {FABRIC_TYPES.map(f => (
              <button
                key={f.id}
                className={`mirror-fabric ${fabric === f.id ? 'active' : ''}`}
                onClick={() => setFabric(f.id)}
                disabled={busy}
              >
                <span className={`mirror-weave weave-${f.id}`} style={{ '--swatch': colorHex }} />
                {f.label}
              </button>
            ))}
          </div>

          <div className="mirror-colors">
            {FABRIC_COLORS.map(c => (
              <button
                key={c.id}
                className={`mirror-color ${colorId === c.id ? 'active' : ''} ${c.id === 'original' ? 'original' : ''}`}
                style={c.hex ? { background: c.hex } : undefined}
                onClick={() => setColorId(c.id)}
                disabled={busy}
                title={c.label}
                aria-label={c.label}
              />
            ))}
            <label className={`mirror-color custom ${colorId === 'custom' ? 'active' : ''}`} title="Custom colour" style={{ background: customHex }}>
              <input
                type="color"
                value={customHex}
                disabled={busy}
                onChange={e => { setCustomHex(e.target.value); setColorId('custom'); }}
              />
            </label>
          </div>
          <p className="mirror-color-name">{fabricLabel}</p>

          <button className="mirror-apply" onClick={apply} disabled={busy || !photo || !selectedKey}>
            <span className="mirror-step-badge sm dark">4</span>
            {loading ? 'AI is fitting the blazer…' : painting ? 'Applying fabric…' : 'Apply ✦'}
          </button>
          <p className="mirror-rail-hint">
            {!photo
              ? 'Add your photo first.'
              : !selectedKey
                ? 'Pick a blazer to continue.'
                : hasAiFit
                  ? 'This blazer is fitted — fabric changes apply instantly.'
                  : 'First fit uses the free AI (~30s). After that, fabric changes are instant.'}
          </p>
        </aside>
      </div>
    </div>
  );
}
