import React, { useState } from 'react';
import '../styles/Header.css';

/**
 * Header.js — Responsive top bar
 * Mobile: compact, shows only brand + hamburger + avatar
 * Desktop: full header with status chips and profile dropdown
 */
function Header({ sidebarOpen, onToggleSidebar, activeModule, onNavigate }) {
  const [profileOpen, setProfileOpen] = useState(false);

  return (
    <header className="header">
      {/* Left: hamburger + brand */}
      <div className="header-left">
        <button
          className="sidebar-toggle"
          onClick={onToggleSidebar}
          aria-label={sidebarOpen ? 'Close navigation' : 'Open navigation'}
        >
          <span className={`hamburger ${sidebarOpen ? 'open' : ''}`}>
            <span /><span /><span />
          </span>
        </button>

        <div className="brand">
          <span className="brand-icon">✦</span>
          <span className="brand-name">TailorAI</span>
          <span className="brand-sub">Virtual Tailor</span>
        </div>
      </div>

      {/* Center: status chips — hidden on mobile */}
      <div className="header-center">
        <span className="status-chip active">● AI Ready</span>
        <span className="status-chip neutral">Camera On</span>
      </div>

      {/* Right: notifications + profile */}
      <div className="header-right">
        <button className="notif-btn" aria-label="Notifications">
          <span className="notif-icon">🔔</span>
          <span className="notif-badge">3</span>
        </button>

        <div className="profile-wrapper">
          <button
            className="profile-btn"
            onClick={() => setProfileOpen(p => !p)}
            aria-haspopup="true"
            aria-expanded={profileOpen}
          >
            <div className="avatar">JS</div>
            <div className="profile-info">
              <span className="profile-name">Manju S.</span>
              <span className="profile-role">Premium</span>
            </div>
            <span className="chevron">{profileOpen ? '▲' : '▼'}</span>
          </button>

          {profileOpen && (
            <>
              {/* Backdrop to close dropdown on mobile */}
              <div className="dropdown-backdrop" onClick={() => setProfileOpen(false)} />
              <div className="profile-dropdown">
                <a href="#profile" onClick={() => setProfileOpen(false)}>My Profile</a>
                <a href="#measurements" onClick={() => setProfileOpen(false)}>Saved Measurements</a>
                <a href="#settings" onClick={() => setProfileOpen(false)}>Settings</a>
                <hr />
                <a href="#logout" className="logout">Sign Out</a>
              </div>
            </>
          )}
        </div>
      </div>
    </header>
  );
}

export default Header;
