import React, { useRef, useEffect, useState, useCallback } from 'react';
import { getAllPrototypes } from '../utils/PrototypeStore';
import '../styles/DressCarousel.css';

/**
 * DressCarousel.js
 *
 * Reads uploaded suit prototype images from PrototypeStore (localStorage).
 * Displays them as scrollable cards. When selected, composites the
 * prototype image onto the captured selfie using <canvas>, scaled,
 * positioned, and tapered to match the body detected by
 * MeasurementProcessor's pose estimation (measurements.keypoints).
 *
 * Props:
 *   selfieImage  — Base64 PNG from CameraCapture
 *   selectedSet  — currently active prototype object | null
 *   onSelectSet  — (proto) => void
 *   measurements — measurementData from MeasurementProcessor
 */

async function detectFaceBox(selfie) {
  if ('FaceDetector' in window) {
    try {
      const detector = new window.FaceDetector();
      const faces = await detector.detect(selfie);
      if (faces.length > 0) {
        return faces[0].boundingBox;
      }
    } catch (err) {
      console.warn('FaceDetector failed, falling back:', err);
    }
  }

  // Fallback: assume the head is in the upper center of the selfie.
  const width = selfie.width * 0.36;
  const height = width * 1.2;
  // Try TensorFlow face-landmarks as a better fallback if available
  try {
    const tf = await import('@tensorflow/tfjs');
    await import('@tensorflow/tfjs-backend-webgl');
    await tf.setBackend('webgl');
    const faceLandmarks = await import('@tensorflow-models/face-landmarks-detection');
    const model = await faceLandmarks.load(faceLandmarks.SupportedPackages.mediapipeFacemesh);
    const predictions = await model.estimateFaces({ input: selfie, returnTensors: false, flipHorizontal: false });
    if (predictions && predictions.length > 0) {
      const p = predictions[0];
      const keypoints = p.scaledMesh || p.keypoints?.map(k => [k.x, k.y]);
      if (keypoints && keypoints.length) {
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (const kp of keypoints) {
          const x = Array.isArray(kp) ? kp[0] : kp[0];
          const y = Array.isArray(kp) ? kp[1] : kp[1];
          if (x < minX) minX = x;
          if (y < minY) minY = y;
          if (x > maxX) maxX = x;
          if (y > maxY) maxY = y;
        }
        const padX = (maxX - minX) * 0.45;
        const padY = (maxY - minY) * 0.6;
        const bx = Math.max(0, minX - padX);
        const by = Math.max(0, minY - padY);
        const bW = Math.min(selfie.width - bx, (maxX - minX) + padX * 2);
        const bH = Math.min(selfie.height - by, (maxY - minY) + padY * 2);
        return { x: bx, y: by, width: bW, height: bH };
      }
    }
  } catch (err) {
    console.warn('Face landmarks detection not available:', err);
  }

  return {
    x: Math.max(0, (selfie.width - width) / 2),
    y: Math.max(0, selfie.height * 0.08),
    width,
    height,
  };
}

function drawHeadOverlay(ctx, selfie, faceBox, canvasWidth, canvasHeight, suitBounds) {
  if (!faceBox) return;

  const marginX = Math.min(faceBox.width * 0.3, selfie.width * 0.15);
  const marginY = Math.min(faceBox.height * 0.45, selfie.height * 0.18);
  const cropX = Math.max(0, faceBox.x - marginX);
  const cropY = Math.max(0, faceBox.y - marginY);
  const cropW = Math.min(selfie.width - cropX, faceBox.width + marginX * 2);
  const cropH = Math.min(selfie.height - cropY, faceBox.height + marginY * 2);

  const headWidth = suitBounds.width * 0.55;
  const headHeight = headWidth * 1.1;
  const headX = suitBounds.x + (suitBounds.width - headWidth) / 2;
  const headY = Math.max(0, suitBounds.y - headHeight * 0.8);

  const temp = document.createElement('canvas');
  temp.width = headWidth;
  temp.height = headHeight;
  const tctx = temp.getContext('2d');

  tctx.save();
  tctx.beginPath();
  tctx.ellipse(headWidth / 2, headHeight / 2, headWidth / 2, headHeight / 2, 0, 0, Math.PI * 2);
  tctx.clip();
  tctx.drawImage(selfie, cropX, cropY, cropW, cropH, 0, 0, headWidth, headHeight);
  tctx.restore();

  ctx.drawImage(temp, headX, headY);
}

/* ── Derive suit placement geometry from detected pose keypoints ──
 * Returns shoulder/hip midpoints & widths (px, in the selfie's own
 * coordinate space) and the shoulder-line tilt angle, or null if the
 * required keypoints weren't confidently detected.
 */
function getPoseGeometry(keypoints) {
  if (!keypoints) return null;
  const get = (name) => {
    const kp = keypoints.find(k => k.name === name);
    return kp && kp.score >= 0.3 ? kp : null;
  };

  const lSh = get('left_shoulder'), rSh = get('right_shoulder');
  const lHip = get('left_hip'), rHip = get('right_hip');
  if (!lSh || !rSh || !lHip || !rHip) return null;

  const shoulderMidX = (lSh.x + rSh.x) / 2;
  const shoulderMidY = (lSh.y + rSh.y) / 2;
  const hipMidX = (lHip.x + rHip.x) / 2;
  const hipMidY = (lHip.y + rHip.y) / 2;

  const shoulderPxWidth = Math.hypot(rSh.x - lSh.x, rSh.y - lSh.y);
  const hipPxWidth = Math.hypot(rHip.x - lHip.x, rHip.y - lHip.y);
  const torsoPxLength = Math.hypot(hipMidX - shoulderMidX, hipMidY - shoulderMidY);
  const angle = Math.atan2(rSh.y - lSh.y, rSh.x - lSh.x); // shoulder-line tilt

  return { shoulderMidX, shoulderMidY, hipMidX, hipMidY, shoulderPxWidth, hipPxWidth, torsoPxLength, angle };
}

/* Tunable multipliers assuming a standard front-facing suit-graphic PNG
 * (blazer top overhangs the shoulders slightly, jacket flares a bit at
 * the hip/waist). Adjust these if your prototype images are framed
 * differently. */
const SUIT_TOP_WIDTH_MULT = 1.85;
const SUIT_BOTTOM_WIDTH_MULT = 2.05;
const SUIT_HEIGHT_MULT = 2.35;
const SUIT_TOP_Y_OFFSET = 0.10; // fraction of suit height the collar sits above shoulder line

function compositeOnCanvas(canvas, selfieDataUrl, prototype, measurements) {
  if (!canvas || !selfieDataUrl) return;
  const ctx = canvas.getContext('2d');
  const selfie = new Image();
  selfie.crossOrigin = 'anonymous';

  selfie.onload = async () => {
    canvas.width = selfie.width;
    canvas.height = selfie.height;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const suit = new Image();
    suit.crossOrigin = 'anonymous';
    suit.onload = async () => {
      const W = canvas.width;
      const H = canvas.height;
      if (!prototype?.imageUrl) {
        ctx.drawImage(selfie, 0, 0);
        return;
      }

      const geo = getPoseGeometry(measurements?.keypoints);
      let suitBounds;

      if (geo) {
        // ── Body-aware placement: scale/taper suit to detected shoulder & hip width ──
        const topWidth = geo.shoulderPxWidth * SUIT_TOP_WIDTH_MULT;
        const bottomWidth = geo.hipPxWidth * SUIT_BOTTOM_WIDTH_MULT;
        const suitHeight = geo.torsoPxLength * SUIT_HEIGHT_MULT;
        const topY = geo.shoulderMidY - suitHeight * SUIT_TOP_Y_OFFSET;
        const halfH = suitHeight * 0.5;

        ctx.save();
        // Rotate around the shoulder midpoint so the suit follows body tilt
        ctx.translate(geo.shoulderMidX, geo.shoulderMidY);
        ctx.rotate(geo.angle);
        ctx.translate(-geo.shoulderMidX, -geo.shoulderMidY);

        ctx.globalAlpha = 0.95;

        // Upper half of the suit graphic, scaled to shoulder/chest width
        ctx.drawImage(
          suit,
          0, 0, suit.width, suit.height * 0.5,
          geo.shoulderMidX - topWidth / 2, topY,
          topWidth, halfH
        );

        // Lower half, tapered independently to hip/waist width — this is what
        // makes a broader or slimmer detected build actually change the fit
        ctx.drawImage(
          suit,
          0, suit.height * 0.5, suit.width, suit.height * 0.5,
          geo.hipMidX - bottomWidth / 2, topY + halfH,
          bottomWidth, halfH
        );

        ctx.restore(); // undo rotation before drawing the (upright) head

        suitBounds = {
          x: Math.min(geo.shoulderMidX - topWidth / 2, geo.hipMidX - bottomWidth / 2),
          y: topY,
          width: Math.max(topWidth, bottomWidth),
          height: suitHeight,
        };
      } else {
        // ── Fallback: no confident pose data, use the old fixed heuristic ──
        const shoulderFraction = measurements
          ? Math.min(0.90, Math.max(0.55, measurements.shoulderWidth / 52))
          : 0.74;
        const torsoFraction = measurements
          ? Math.min(0.75, Math.max(0.50, measurements.torsoLength / 88))
          : 0.62;

        const drawW = W * shoulderFraction;
        const drawH = H * torsoFraction;
        const drawX = (W - drawW) / 2;
        const drawY = H * 0.23;

        ctx.save();
        ctx.globalAlpha = 0.95;
        ctx.drawImage(suit, drawX, drawY, drawW, drawH);
        ctx.restore();

        suitBounds = { x: drawX, y: drawY, width: drawW, height: drawH };
      }

      const faceBox = await detectFaceBox(selfie);
      drawHeadOverlay(ctx, selfie, faceBox, W, H, suitBounds);
    };

    suit.src = prototype?.imageUrl || '';
  };

  selfie.src = selfieDataUrl;
}

/* ── Component ───────────────────────────────────────────────── */
function DressCarousel({ selfieImage, selectedSet, onSelectSet, measurements }) {
  const canvasRef    = useRef(null);
  const carouselRef  = useRef(null);
  const [prototypes, setPrototypes] = useState([]);
  const [canScroll,  setCanScroll]  = useState({ left: false, right: true });

  useEffect(() => {
    getAllPrototypes().then(setPrototypes).catch(() => setPrototypes([]));
  }, []);

  useEffect(() => {
    if (!selfieImage) return;
    compositeOnCanvas(canvasRef.current, selfieImage, selectedSet, measurements);
  }, [selfieImage, selectedSet, measurements]);

  const updateScrollState = useCallback(() => {
    const el = carouselRef.current;
    if (!el) return;
    setCanScroll({
      left:  el.scrollLeft > 0,
      right: el.scrollLeft + el.clientWidth < el.scrollWidth - 4,
    });
  }, []);

  const scrollBy = (dir) => {
    carouselRef.current?.scrollBy({ left: dir * 240, behavior: 'smooth' });
  };

  if (!selfieImage) return null;

  return (
    <div className="dress-carousel-section">

      <div className="canvas-wrapper">
        <canvas ref={canvasRef} className="try-on-canvas" />

        {selectedSet && (
          <div className="canvas-label">
            <span className="canvas-label-dot" style={{ background: selectedSet.blazerColor }} />
            {selectedSet.name}
          </div>
        )}

        {!selectedSet && (
          <div className="canvas-hint">← Pick a suit below to try it on</div>
        )}

        {measurements && selectedSet && (
          <div className="canvas-fit-info">
            <span>📐</span>
            <span>
              Fitted to your {measurements.bodyProfileLabel || 'detected'} build
              · {measurements.shoulderWidth}cm shoulder · {measurements.waistCirc}cm waist
              {measurements.estimationMethod === 'simulated' && ' (approx.)'}
            </span>
          </div>
        )}
      </div>

      <div className="carousel-container">
        <h3 className="carousel-title">Your Suit Prototypes</h3>
        <p className="carousel-sub">
          {prototypes.length === 0
            ? 'No prototypes uploaded yet — go to Prototype Manager to add suits.'
            : `${prototypes.length} suit${prototypes.length !== 1 ? 's' : ''} available — scroll to browse`}
        </p>

        {prototypes.length === 0 && (
          <div className="carousel-empty">
            <span>👔</span>
            <p>Upload suit images in the Prototype Manager and they'll appear here.</p>
          </div>
        )}

        {prototypes.length > 0 && (
          <div className="carousel-track-wrap">
            {canScroll.left && (
              <button className="scroll-btn left" onClick={() => scrollBy(-1)}>‹</button>
            )}

            <div ref={carouselRef} className="carousel-track" onScroll={updateScrollState}>
              {prototypes.map(proto => (
                <button
                  key={proto.id}
                  className={`dress-card ${selectedSet?.id === proto.id ? 'selected' : ''}`}
                  onClick={() => onSelectSet(proto)}
                >
                  <div className="dress-preview">
                    <div className="dress-checker" />
                    <img src={proto.imageUrl} alt={proto.name} className="dress-preview-img" />
                    {selectedSet?.id === proto.id && (
                      <span className="selected-check">✓</span>
                    )}
                  </div>

                  <div className="dress-info">
                    <span className="dress-name">{proto.name}</span>
                    {proto.description && (
                      <span className="dress-desc">{proto.description}</span>
                    )}
                    {proto.tags && proto.tags.length > 0 && (
                      <div className="dress-tags">
                        {proto.tags.slice(0, 3).map(t => (
                          <span key={t} className="dress-tag">{t}</span>
                        ))}
                      </div>
                    )}
                    <div className="dress-swatches">
                      <span className="swatch" style={{ background: proto.blazerColor }} title="Blazer" />
                      <span className="swatch" style={{ background: proto.tieColor }} title="Tie" />
                    </div>
                  </div>
                </button>
              ))}
            </div>

            {canScroll.right && (
              <button className="scroll-btn right" onClick={() => scrollBy(1)}>›</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default DressCarousel;