/**
 * fabricCore.mjs — pixel code shared by the server and the browser (pure, no DOM).
 *
 * Chroma-key try-on:
 *   1. Server: find the blazer in the garment product photo and paint it KEY green
 *      (shirt, tie and hands untouched) before sending it to the AI model
 *   2. AI: dresses the customer in that green blazer
 *   3. Browser: every green pixel in the result is the blazer — repaint it in any
 *      fabric colour / weave, keeping the AI's folds and shading. Instant and free.
 *
 * All images are RGBA Uint8ClampedArray / Buffer of size W×H×4.
 */

export const KEY_COLOR = '#22b14c';

export const hexToRgb = hex => {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};

export const rgbToHex = ([r, g, b]) => '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');

const lum = (r, g, b) => (0.299 * r + 0.587 * g + 0.114 * b) / 255;

const isSkin = (r, g, b) =>
  r > 95 && g > 40 && b > 20 && r > g && r > b && r - g > 15 && Math.max(r, g, b) - Math.min(r, g, b) > 15;

/* Deterministic per-pixel noise in [0, 1) */
const hash = (x, y) => {
  let h = (x * 374761393 + y * 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};

/* Box-filter a Float32 map with radius r (separable, O(n)) */
function boxBlur(src, W, H, r) {
  if (r < 1) return src;
  const tmp = new Float32Array(W * H);
  const out = new Float32Array(W * H);
  const win = 2 * r + 1;
  for (let y = 0; y < H; y++) {
    let acc = 0;
    const row = y * W;
    for (let x = -r; x <= r; x++) acc += src[row + Math.min(W - 1, Math.max(0, x))];
    for (let x = 0; x < W; x++) {
      tmp[row + x] = acc / win;
      acc += src[row + Math.min(W - 1, x + r + 1)] - src[row + Math.max(0, x - r)];
    }
  }
  for (let x = 0; x < W; x++) {
    let acc = 0;
    for (let y = -r; y <= r; y++) acc += tmp[Math.min(H - 1, Math.max(0, y)) * W + x];
    for (let y = 0; y < H; y++) {
      out[y * W + x] = acc / win;
      acc += tmp[Math.min(H - 1, y + r + 1) * W + x] - tmp[Math.max(0, y - r) * W + x];
    }
  }
  return out;
}

/* Weave pattern: { mul } brightness multiplier, { mix } amount of lighter "thread" colour */
function weave(type, x, y, s) {
  switch (type) {
    case 'flat':
      return { mul: 1, mix: 0 };
    case 'pinstripe':
      return { mul: 1, mix: (x % (13 * s)) < 1.1 * s ? 0.5 : 0 };
    case 'chalkstripe': {
      const p = 24 * s;
      const d = Math.abs((x % p) - p / 2) / (2.2 * s);
      return { mul: 1, mix: d < 1 ? 0.32 * (1 - d) : 0 };
    }
    case 'check': {
      const p = 42 * s;
      return { mul: 1, mix: (x % p) < 1.4 * s || (y % p) < 1.4 * s ? 0.38 : 0 };
    }
    case 'herringbone': {
      const band = Math.floor(x / (7 * s)) % 2;
      const v = ((band ? x + y : x - y) % (5 * s) + 5 * s) % (5 * s) < 2.5 * s;
      return { mul: v ? 1.1 : 0.9, mix: 0 };
    }
    case 'tweed':
      return { mul: 0.86 + 0.28 * hash(x >> 1, y >> 1), mix: hash(x, y) > 0.93 ? 0.35 : 0 };
    case 'linen': {
      const slub = 0.94 + 0.12 * hash(0, Math.floor(y / (2 * s))) * hash(Math.floor(x / (9 * s)), 7);
      return { mul: slub * (0.97 + 0.06 * hash(Math.floor(x / s), 3)), mix: 0 };
    }
    case 'velvet':
    case 'plain':
    default:
      return { mul: 0.97 + 0.06 * hash(x, y), mix: 0 };
  }
}

/**
 * Find the blazer in a garment product photo (white background).
 * Returns { alpha: Float32Array (soft 0..1), color: [r,g,b] median blazer colour }
 */
export function garmentBlazerMask(rgba, W, H) {
  const N = W * H;

  // Rough blazer brightness first, so "light" (shirt / background) can be judged
  // relative to it — a shaded white shirt is grey, but still much lighter than the blazer
  const rough = [];
  for (let i = 0, p = 0; i < N; i += 7, p += 28) {
    const r = rgba[p], g = rgba[p + 1], b = rgba[p + 2];
    if ((r < 225 || g < 225 || b < 225) && !isSkin(r, g, b)) rough.push(lum(r, g, b));
  }
  rough.sort((a, b) => a - b);
  const roughL = rough.length ? rough[rough.length >> 1] : 0.15;
  const lightL = Math.min(0.85, Math.max(0.5, roughL + 0.3));

  const solid = new Uint8Array(N);
  let minX = W, maxX = -1;
  for (let i = 0, p = 0; i < N; i++, p += 4) {
    const r = rgba[p], g = rgba[p + 1], b = rgba[p + 2];
    const light = lum(r, g, b) > lightL && Math.max(r, g, b) - Math.min(r, g, b) < 40;
    if (!light && (r < 225 || g < 225 || b < 225) && !isSkin(r, g, b)) {
      solid[i] = 1;
      const x = i % W;
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
    }
  }
  if (maxX < 0) return { alpha: new Float32Array(N), color: [40, 40, 45] };

  // The shirt "V" (and the tie inside it): white gaps enclosed by garment in the
  // central part of a row — clear everything from the first such gap to the last
  const cLo = minX + (maxX - minX) * 0.25, cHi = minX + (maxX - minX) * 0.75;
  const tieSum = [0, 0, 0];
  let tieN = 0, vRow = -1, vLo = 0, vHi = 0;
  for (let y = 0; y < H; y++) {
    const row = y * W;
    let first = -1, last = -1, seenSolid = false, gapStart = -1;
    for (let x = minX; x <= maxX; x++) {
      if (solid[row + x]) {
        if (gapStart >= 0 && seenSolid && x - 1 >= cLo && gapStart <= cHi) {
          if (first < 0) first = gapStart;
          last = x - 1;
        }
        gapStart = -1;
        seenSolid = true;
      } else if (gapStart < 0) {
        gapStart = x;
      }
    }
    if (first < 0) continue;
    let lo = W, hi = -1;
    for (let x = first; x <= last; x++) {
      if (!solid[row + x]) continue;
      const p = (row + x) * 4; // a solid pixel inside the V is the tie
      tieSum[0] += rgba[p]; tieSum[1] += rgba[p + 1]; tieSum[2] += rgba[p + 2]; tieN++;
      lo = Math.min(lo, x); hi = Math.max(hi, x);
      solid[row + x] = 0;
    }
    if (hi >= 0) { vRow = y; vLo = lo; vHi = hi; }
  }

  // Below the V the tie runs on between the lapels — follow it down by colour
  if (tieN > 30 && vRow >= 0) {
    const tie = tieSum.map(v => v / tieN);
    const blz = [0, 0, 0];
    let bn = 0;
    for (let i = 0, p = 0; i < N; i += 5, p += 20) {
      if (solid[i]) { blz[0] += rgba[p]; blz[1] += rgba[p + 1]; blz[2] += rgba[p + 2]; bn++; }
    }
    blz.forEach((v, c) => { blz[c] = v / Math.max(1, bn); });
    const dist = (p, ref) => Math.abs(rgba[p] - ref[0]) + Math.abs(rgba[p + 1] - ref[1]) + Math.abs(rgba[p + 2] - ref[2]);
    const pad = Math.round(0.01 * W);
    let misses = 0;
    for (let y = vRow + 1; y < H && misses < 4; y++) {
      const row = y * W;
      let lo = W, hi = -1, hits = 0;
      for (let x = Math.max(0, vLo - pad); x <= Math.min(W - 1, vHi + pad); x++) {
        if (solid[row + x] && dist((row + x) * 4, tie) < dist((row + x) * 4, blz)) { hits++; lo = Math.min(lo, x); hi = Math.max(hi, x); }
      }
      if (hits < Math.max(3, (vHi - vLo) * 0.3)) { misses++; continue; }
      misses = 0;
      for (let x = lo; x <= hi; x++) solid[row + x] = 0; // dotted ties: clear the whole span
      vLo = lo; vHi = hi;
    }
  }

  // Blazer = the dominant colour among what is left (drops buttons, pocket squares…)
  const idx = [];
  for (let i = 0; i < N; i += 2) if (solid[i]) idx.push(i);
  if (idx.length < 100) return { alpha: new Float32Array(N), color: [40, 40, 45] };
  const lumAt = i => lum(rgba[i * 4], rgba[i * 4 + 1], rgba[i * 4 + 2]);
  idx.sort((a, b) => lumAt(a) - lumAt(b));
  const m = idx[idx.length >> 1];
  const color = [rgba[m * 4], rgba[m * 4 + 1], rgba[m * 4 + 2]];
  const refL = lum(...color), tolL = Math.max(0.25, refL * 0.9);

  const mask = new Float32Array(N);
  for (let i = 0, p = 0; i < N; i++, p += 4) {
    if (solid[i] && Math.abs(lum(rgba[p], rgba[p + 1], rgba[p + 2]) - refL) < tolL) mask[i] = 1;
  }
  return { alpha: boxBlur(mask, W, H, 1), color };
}

/* Soft mask of KEY-green pixels in an AI result */
export function keyAlpha(rgba, W, H) {
  const N = W * H;
  const a = new Float32Array(N);
  for (let i = 0, p = 0; i < N; i++, p += 4) {
    const d = rgba[p + 1] - Math.max(rgba[p], rgba[p + 2]);
    a[i] = Math.max(0, Math.min(1, (d - 14) / 26));
  }
  return a;
}

/**
 * Repaint the masked area in a fabric colour + weave, keeping its light and shadow.
 * options: { color: '#rrggbb', fabric, despill } — despill removes green fringes
 * returns a new RGBA array
 */
export function paintFabric(rgba, alpha, W, H, { color, fabric = 'plain', despill = false }) {
  const N = W * H;
  const s = W / 768; // pattern scale relative to the model's 768px width
  const out = new Uint8ClampedArray(rgba);

  // Shading range from the area's own luminance (5th–95th percentile)
  const hist = new Uint32Array(256);
  let count = 0;
  for (let i = 0, p = 0; i < N; i++, p += 4) {
    if (alpha[i] > 0.5) { hist[Math.min(255, (lum(rgba[p], rgba[p + 1], rgba[p + 2]) * 255) | 0)]++; count++; }
  }
  if (!count) return out;
  const pct = q => { let acc = 0; for (let v = 0; v < 256; v++) { acc += hist[v]; if (acc >= q * count) return v / 255; } return 1; };
  const lo = pct(0.05), hi = Math.max(pct(0.95), lo + 0.04);

  const target = hexToRgb(color);
  const thread = target.map(c => Math.min(255, c + (255 - c) * 0.55 + 25));
  const velvet = fabric === 'velvet';
  const fringe = despill ? boxBlur(alpha, W, H, Math.max(2, Math.round(2 * s))) : null;

  for (let i = 0, p = 0; i < N; i++, p += 4) {
    let r = rgba[p], g = rgba[p + 1], b = rgba[p + 2];
    if (fringe && fringe[i] > 0.01) {
      g = Math.min(g, Math.max(r, b) + 6); // strip green spill from edges
      out[p + 1] = g;
    }
    const a = alpha[i];
    if (a < 0.01) continue;
    const x = i % W, y = (i / W) | 0;
    let sh = (lum(rgba[p], rgba[p + 1], rgba[p + 2]) - lo) / (hi - lo);
    sh = Math.max(0, Math.min(1.25, sh));
    const f = velvet ? 0.3 + 1.05 * Math.pow(sh, 1.4) : 0.55 + 0.72 * sh;
    const spec = Math.pow(Math.max(0, sh - 0.75), 2) * 120; // keep highlights on dark fabrics
    const w = weave(fabric, x, y, s);
    const src = [r, g, b];
    for (let c = 0; c < 3; c++) {
      let v = target[c] * f * w.mul + spec;
      v = v * (1 - w.mix) + thread[c] * f * w.mix;
      out[p + c] = src[c] * (1 - a) + Math.min(255, v) * a;
    }
  }
  return out;
}

/* Garment product photo → same photo with the blazer painted KEY green */
export function keyGarment(rgba, W, H) {
  const { alpha, color } = garmentBlazerMask(rgba, W, H);
  return { data: paintFabric(rgba, alpha, W, H, { color: KEY_COLOR, fabric: 'flat' }), color };
}
