import React, { useState, useEffect, useRef, useCallback } from 'react';
import '../styles/MeasurementProcessor.css';

/**
 * MeasurementProcessor.js
 *
 * Runs real body-pose estimation (TensorFlow.js MoveNet) on the selfie to
 * derive shoulder width, hip width, torso length, and build classification.
 * If pose detection fails (model unavailable, no person detected, etc.) it
 * falls back to a plausible simulated profile so the flow never breaks.
 *
 * Requires (add to package.json if not already present):
 *   npm install @tensorflow/tfjs @tensorflow/tfjs-backend-webgl @tensorflow-models/pose-detection
 *
 * Props:
 *   selfieImage:     Base64 string of the captured photo
 *   onMeasurements:  (measurementData) => void — called when analysis completes
 */

/* ── Body profile types ─────────────────────────────────────────── */
const BODY_PROFILES = {
  athletic: {
    label: 'Athletic Build',
    icon: '💪',
    desc: 'Broad shoulders, narrow waist',
  },
  slim: {
    label: 'Slim Build',
    icon: '🧍',
    desc: 'Lean frame, narrow profile',
  },
  regular: {
    label: 'Regular Build',
    icon: '🧑',
    desc: 'Average proportions',
  },
  broad: {
    label: 'Broad Build',
    icon: '🏋️',
    desc: 'Wide shoulders and chest',
  },
};

/* ── Skin tone analysis mock (color-based estimate is out of scope here) ── */
const SKIN_TONES = [
  { label: 'Fair',   hex: '#fde8d0', recommendation: 'Navy and charcoal blazers complement your tone beautifully.' },
  { label: 'Light',  hex: '#f5c99a', recommendation: 'Earthy tones and forest green will elevate your look.' },
  { label: 'Medium', hex: '#c68642', recommendation: 'Rich jewel tones and midnight black suit you well.' },
  { label: 'Olive',  hex: '#8d6024', recommendation: 'Caramel, burgundy, and slate blazers are ideal choices.' },
  { label: 'Dark',   hex: '#4a2e1a', recommendation: 'High-contrast combos like white shirts with dark blazers shine.' },
];

const KEYPOINT_SCORE_THRESHOLD = 0.3;

/* ── Pose detection ──────────────────────────────────────────────
 * Lazy-loads TF.js + MoveNet (same lazy-import pattern already used
 * for face-landmarks detection in DressCarousel.js) and returns the
 * raw keypoints array in image-pixel coordinates, or null on failure.
 */
async function detectPoseKeypoints(imgEl) {
  try {
    const tf = await import('@tensorflow/tfjs');
    await import('@tensorflow/tfjs-backend-webgl');
    await tf.setBackend('webgl');
    await tf.ready();

    const poseDetection = await import('@tensorflow-models/pose-detection');
    const detector = await poseDetection.createDetector(
      poseDetection.SupportedModels.MoveNet,
      { modelType: poseDetection.movenet.modelType.SINGLEPOSE_THUNDER }
    );

    const poses = await detector.estimatePoses(imgEl);
    if (poses && poses.length > 0 && poses[0].keypoints?.length) {
      return poses[0].keypoints; // [{ x, y, score, name }, ...]
    }
  } catch (err) {
    console.warn('Pose detection unavailable, falling back to estimated profile:', err);
  }
  return null;
}

function findKp(keypoints, name) {
  const kp = keypoints.find(k => k.name === name);
  return kp && kp.score >= KEYPOINT_SCORE_THRESHOLD ? kp : null;
}

/* ── Pixel → cm scale factor ──────────────────────────────────────
 * Prefers nose-to-ankle pixel span vs. a known/assumed real height.
 * Falls back to an average adult shoulder-width anchor if the full
 * body isn't visible in frame.
 */
function computePxToCm(keypoints, assumedHeightCm) {
  const nose    = findKp(keypoints, 'nose');
  const lAnkle  = findKp(keypoints, 'left_ankle');
  const rAnkle  = findKp(keypoints, 'right_ankle');
  const lShoulder = findKp(keypoints, 'left_shoulder');
  const rShoulder = findKp(keypoints, 'right_shoulder');

  if (nose && (lAnkle || rAnkle)) {
    const ankleY = lAnkle && rAnkle ? (lAnkle.y + rAnkle.y) / 2 : (lAnkle || rAnkle).y;
    const spanPx = ankleY - nose.y; // nose→ankle ≈ ~94% of full standing height
    if (spanPx > 10) return (assumedHeightCm * 0.94) / spanPx;
  }
  if (lShoulder && rShoulder) {
    const shoulderPx = Math.hypot(rShoulder.x - lShoulder.x, rShoulder.y - lShoulder.y);
    if (shoulderPx > 5) return 45 / shoulderPx; // avg adult biacromial width anchor
  }
  return null;
}

/* ── Turn detected keypoints into tailoring measurements ─────────── */
function measurementsFromPose(keypoints, assumedHeightCm) {
  const lSh  = findKp(keypoints, 'left_shoulder');
  const rSh  = findKp(keypoints, 'right_shoulder');
  const lHip = findKp(keypoints, 'left_hip');
  const rHip = findKp(keypoints, 'right_hip');
  if (!lSh || !rSh || !lHip || !rHip) return null;

  const pxToCm = computePxToCm(keypoints, assumedHeightCm);
  if (!pxToCm) return null;

  const shoulderMidX = (lSh.x + rSh.x) / 2;
  const shoulderMidY = (lSh.y + rSh.y) / 2;
  const hipMidX = (lHip.x + rHip.x) / 2;
  const hipMidY = (lHip.y + rHip.y) / 2;

  const shoulderPxWidth = Math.hypot(rSh.x - lSh.x, rSh.y - lSh.y);
  const hipPxWidth      = Math.hypot(rHip.x - lHip.x, rHip.y - lHip.y);
  const torsoPxLength   = Math.hypot(hipMidX - shoulderMidX, hipMidY - shoulderMidY);

  const shoulderWidth = Math.round(shoulderPxWidth * pxToCm);
  const hipWidth       = Math.round(hipPxWidth * pxToCm);
  const torsoLength    = Math.round(torsoPxLength * pxToCm);

  // Sleeve length from actual arm keypoints where available, else height-based estimate
  const lElbow = findKp(keypoints, 'left_elbow');
  const lWrist = findKp(keypoints, 'left_wrist');
  const rElbow = findKp(keypoints, 'right_elbow');
  const rWrist = findKp(keypoints, 'right_wrist');
  let sleeveLength;
  const armPx = (a, b, c) => a && b && c
    ? Math.hypot(b.x - a.x, b.y - a.y) + Math.hypot(c.x - b.x, c.y - b.y)
    : null;
  const leftArmPx  = armPx(lSh, lElbow, lWrist);
  const rightArmPx = armPx(rSh, rElbow, rWrist);
  const armPxSamples = [leftArmPx, rightArmPx].filter(Boolean);
  if (armPxSamples.length) {
    sleeveLength = Math.round((armPxSamples.reduce((a, b) => a + b, 0) / armPxSamples.length) * pxToCm);
  } else {
    sleeveLength = Math.round(assumedHeightCm * 0.36);
  }

  // Rough circumference estimates from front-view widths (ellipse approximation)
  const chestCirc = Math.round(shoulderWidth * 2.2);
  const waistCirc  = Math.round(hipWidth * 2.35);
  const neckSize   = Math.round(shoulderWidth * 0.82);

  // Build classification from real proportions (not random)
  const sizeIndex  = shoulderWidth / assumedHeightCm;   // overall frame size
  const taperIndex = hipWidth / shoulderWidth;          // V-taper: lower = athletic, higher = fuller

  let profileKey;
  if (sizeIndex < 0.235 && taperIndex < 0.90) {
    profileKey = 'slim';
  } else if (taperIndex < 0.82) {
    profileKey = 'athletic';
  } else if (taperIndex > 0.97) {
    profileKey = 'broad';
  } else {
    profileKey = 'regular';
  }

  const skinTone = SKIN_TONES[Math.floor(Math.random() * SKIN_TONES.length)]; // color estimation out of scope
  const profile = BODY_PROFILES[profileKey];

  return {
    neckSize,
    shoulderWidth,
    chestCirc,
    waistCirc,
    sleeveLength,
    torsoLength,

    heightCm: assumedHeightCm,
    bodyProfile: profileKey,
    bodyProfileLabel: profile.label,
    bodyProfileDesc: profile.desc,
    skinTone: skinTone.label,
    skinToneHex: skinTone.hex,
    skinToneRec: skinTone.recommendation,

    broadShoulder: shoulderWidth >= 48,
    slimFit: profileKey === 'slim',
    analyzedAt: new Date().toISOString(),

    // Raw pixel-space data DressCarousel uses to actually place/scale the suit
    keypoints,
    estimationMethod: 'pose',
  };
}

/* ── Fallback when pose detection isn't available ─────────────────
 * Same shape of output so downstream components never break, just
 * flagged so the UI can tell the user it's an approximation.
 */
function fallbackMeasurements(assumedHeightCm) {
  const profileKeys = Object.keys(BODY_PROFILES);
  const profileKey  = profileKeys[Math.floor(Math.random() * profileKeys.length)];
  const profile     = BODY_PROFILES[profileKey];
  const skinTone    = SKIN_TONES[Math.floor(Math.random() * SKIN_TONES.length)];

  const mod = { athletic: [3, -2, 4], slim: [-2, -3, -2], regular: [0, 0, 0], broad: [5, 2, 6] }[profileKey];
  const base = {
    neck: 37 + Math.round(Math.random() * 5),
    shoulder: 44 + Math.round(Math.random() * 6),
    chest: 92 + Math.round(Math.random() * 10),
    waist: 80 + Math.round(Math.random() * 12),
    sleeve: 62 + Math.round(Math.random() * 6),
    torso: 65 + Math.round(Math.random() * 10),
  };

  return {
    neckSize: base.neck,
    shoulderWidth: base.shoulder + mod[2],
    chestCirc: base.chest + mod[0],
    waistCirc: base.waist + mod[1],
    sleeveLength: base.sleeve,
    torsoLength: base.torso,

    heightCm: assumedHeightCm,
    bodyProfile: profileKey,
    bodyProfileLabel: profile.label,
    bodyProfileDesc: profile.desc,
    skinTone: skinTone.label,
    skinToneHex: skinTone.hex,
    skinToneRec: skinTone.recommendation,

    broadShoulder: (base.shoulder + mod[2]) >= 48,
    slimFit: profileKey === 'slim',
    analyzedAt: new Date().toISOString(),

    keypoints: null,
    estimationMethod: 'simulated',
  };
}

const delay = ms => new Promise(res => setTimeout(res, ms));

/* ── Component ───────────────────────────────────────────────────── */
function MeasurementProcessor({ selfieImage, onMeasurements }) {
  const [status, setStatus] = useState('idle');
  const [measurements, setMeasurements] = useState(null);
  const [progress, setProgress] = useState(0);
  const [heightCm, setHeightCm] = useState(175);

  const analysisStarted = useRef(false);

  const runAnalysis = useCallback(async () => {
    setStatus('analyzing');
    setProgress(0);

    const stages = [
      { label: 'Loading pose model…',            pct: 15 },
      { label: 'Detecting body landmarks…',       pct: 40 },
      { label: 'Measuring shoulder & hip width…', pct: 62 },
      { label: 'Estimating torso & sleeve…',      pct: 80 },
      { label: 'Analysing skin tone…',            pct: 90 },
      { label: 'Finalising measurements…',        pct: 100 },
    ];

    // Kick off real pose detection in parallel with the staged UI animation
    const imgEl = new Image();
    imgEl.crossOrigin = 'anonymous';
    const poseWork = new Promise((resolve) => {
      imgEl.onload = async () => {
        const kps = await detectPoseKeypoints(imgEl);
        resolve(kps);
      };
      imgEl.onerror = () => resolve(null);
      imgEl.src = selfieImage;
    });

    for (const stage of stages) {
      await delay(380 + Math.random() * 260);
      setProgress(stage.pct);
    }

    const keypoints = await poseWork;
    const data = (keypoints && measurementsFromPose(keypoints, heightCm))
      || fallbackMeasurements(heightCm);

    setMeasurements(data);
    setStatus('done');
    onMeasurements(data);
  }, [selfieImage, heightCm, onMeasurements]);

  useEffect(() => {
    if (!selfieImage) return;
    if (analysisStarted.current) return;
    analysisStarted.current = true;
    runAnalysis();
  }, [selfieImage, runAnalysis]);

  const reAnalyze = useCallback(() => {
    analysisStarted.current = false;
    setStatus('idle');
    setMeasurements(null);
    setProgress(0);
    setTimeout(() => {
      analysisStarted.current = true;
      runAnalysis();
    }, 80);
  }, [runAnalysis]);

  if (!selfieImage) return null;

  return (
    <div className="measurement-processor">
      <div className="mp-header">
        <h3>AI Body Analysis</h3>
        <span className="mp-badge">Smart Fit Engine</span>
      </div>

      {/* Optional height input improves cm-scale accuracy; doesn't affect on-photo fit */}
      {status === 'idle' && (
        <div className="mp-height-input">
          <label htmlFor="mp-height">Your height (optional, improves cm accuracy)</label>
          <input
            id="mp-height"
            type="number"
            min="140"
            max="220"
            value={heightCm}
            onChange={e => setHeightCm(Number(e.target.value) || 175)}
          />
          <span>cm</span>
        </div>
      )}

      {status === 'analyzing' && (
        <div className="mp-analyzing">
          <div className="scan-animation">
            <div className="scan-figure">
              <div className="sf-head" />
              <div className="sf-body" />
              <div className="sf-beam" style={{ top: `${progress}%` }} />
            </div>
          </div>
          <div className="mp-progress-wrap">
            <div className="mp-progress-bar">
              <div className="mp-progress-fill" style={{ width: `${progress}%` }} />
            </div>
            <span className="mp-progress-pct">{progress}%</span>
          </div>
          <p className="mp-stage-label">Scanning your body profile…</p>
        </div>
      )}

      {status === 'done' && measurements && (
        <div className="mp-results">
          <div className="profile-card">
            <span className="profile-icon">
              {BODY_PROFILES[measurements.bodyProfile]?.icon}
            </span>
            <div>
              <span className="profile-label">{measurements.bodyProfileLabel}</span>
              <span className="profile-desc">{measurements.bodyProfileDesc}</span>
            </div>
            <div className="skin-chip">
              <span className="skin-dot" style={{ background: measurements.skinToneHex }} />
              {measurements.skinTone} skin
            </div>
          </div>

          {measurements.estimationMethod === 'simulated' && (
            <div className="tone-rec" style={{ background: '#fff4e5' }}>
              ⚠ Couldn't detect a full body pose in this photo — showing an approximate
              profile. For an accurate fit, use a well-lit, front-facing, full-body photo.
            </div>
          )}

          <div className="tone-rec">💡 {measurements.skinToneRec}</div>

          <div className="measurements-grid">
            {[
              { label: 'Neck',     value: measurements.neckSize,     unit: 'cm' },
              { label: 'Shoulder', value: measurements.shoulderWidth, unit: 'cm' },
              { label: 'Chest',    value: measurements.chestCirc,     unit: 'cm' },
              { label: 'Waist',    value: measurements.waistCirc,     unit: 'cm' },
              { label: 'Sleeve',   value: measurements.sleeveLength,  unit: 'cm' },
              { label: 'Torso',    value: measurements.torsoLength,   unit: 'cm' },
              { label: 'Height',   value: measurements.heightCm,      unit: 'cm' },
            ].map(m => (
              <div className="m-cell" key={m.label}>
                <span className="m-value">{m.value}<span className="m-unit">{m.unit}</span></span>
                <span className="m-label">{m.label}</span>
              </div>
            ))}
          </div>

          <div className="fit-flags">
            {measurements.broadShoulder && <span className="flag flag-broad">⬛ Broad Shoulder Cut</span>}
            {measurements.slimFit && <span className="flag flag-slim">▭ Slim Fit Recommended</span>}
            <span className="flag flag-height">
              {measurements.heightCm >= 180 ? '↑ Tall fit' : measurements.heightCm <= 168 ? '↓ Short fit' : '— Regular fit'}
            </span>
          </div>

          <button className="re-analyze-btn" onClick={reAnalyze}>↺ Re-analyse</button>
        </div>
      )}
    </div>
  );
}

export default MeasurementProcessor;