const loadImage = src => new Promise((resolve, reject) => {
  const img = new Image();
  img.crossOrigin = 'anonymous'; // results come from the backend host
  img.onload = () => resolve(img);
  img.onerror = () => reject(new Error('Could not load the try-on image.'));
  img.src = src;
});

/* Paint the green blazer in `resultUrl` with a fabric; returns a JPEG data URL */
export async function renderFabric({ resultUrl, color, fabric }) {
  const img = await loadImage(resultUrl);
  const W = img.naturalWidth, H = img.naturalHeight;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(img, 0, 0);
  const pixels = ctx.getImageData(0, 0, W, H);
  const out = paintFabric(pixels.data, keyAlpha(pixels.data, W, H), W, H, { color, fabric, despill: true });
  pixels.data.set(out);
  ctx.putImageData(pixels, 0, 0);
  return canvas.toDataURL('image/jpeg', 0.93);
}
