import React from 'react';
import VirtualTailor from './VirtualTailor';
import PrototypeManager from './PrototypeManager';
import AIOutfitChanger from './AIOutfitChanger'; // 
import '../styles/Dashboard.css';

/**
 * Dashboard.js
 * Conditionally renders the correct module based on activeModule.
 * Acts as the content router for the main area.
 */
function Dashboard({ activeModule, onNavigate }) {
  return (
    <div className="dashboard">
      {activeModule === 'home'   && <HomeModule onNavigate={onNavigate} />}
      {activeModule === 'tailor' && <VirtualTailor onNavigate={onNavigate} />}
      {activeModule === 'protos' && <PrototypeManager />}
      {activeModule === 'saved'  && <SavedFitsModule />}
      {activeModule === 'orders' && <OrdersModule />}
      {activeModule === 'AIOutFitChange' && <AIOutfitChange onNavigate={onNavigate} />}
    </div>
  );
}
function AIOutfitChange({ onNavigate }) {
  return (
    <div className="module ai-outfit-module">
      <AIOutfitChanger onNavigate={onNavigate} />
    </div>
  );
}
/* ── Home / Overview module ─────────────────────────────────────── */
function HomeModule({ onNavigate }) {
  const stats = [
    { label: 'Looks Saved',    value: '12',   icon: '♡', color: 'rose' },
    { label: 'Orders Placed',  value: '3',    icon: '📦', color: 'amber' },
    { label: 'Blazers Tried',  value: '28',   icon: '✂', color: 'indigo' },
    { label: 'AI Scans Done',  value: '9',    icon: '◎', color: 'teal' },
  ];

  return (
    <div className="module home-module">
      {/* Hero welcome */}
      <div className="home-hero">
        <div className="hero-text">
          <h1 className="hero-title">Welcome back, <span className="hero-name">Manju</span></h1>
          <p className="hero-sub">
            Your next perfect blazer is one selfie away. Let our AI tailor measure, style, and stitch — just for you.
          </p>
          <button className="cta-btn" onClick={() => onNavigate('tailor')}>
            Start Virtual Try-On ✦
          </button>
        </div>
        <div className="hero-visual">
          <div className="hero-mannequin">
            <div className="mannequin-body">
              <div className="mannequin-head" />
              <div className="mannequin-torso" />
              <div className="mannequin-suit-line" />
            </div>
            <div className="scan-ring" />
            <div className="scan-line" />
          </div>
        </div>
      </div>

      {/* Stats row */}
      <div className="stats-row">
        {stats.map(s => (
          <div className={`stat-card ${s.color}`} key={s.label}>
            <span className="stat-icon">{s.icon}</span>
            <span className="stat-value">{s.value}</span>
            <span className="stat-label">{s.label}</span>
          </div>
        ))}
      </div>

      {/* Quick actions */}
      <div className="quick-actions">
        <h2 className="section-title">Quick Actions</h2>
        <div className="action-grid">
          {[
            { label: 'New Try-On Session', icon: '📷', module: 'tailor', desc: 'Capture & fit a dress set now' },
            { label: 'My Saved Looks',     icon: '♡',  module: 'saved',  desc: 'Browse your saved combinations' },
            { label: 'Track Orders',       icon: '📦', module: 'orders', desc: 'Check stitching progress' },
          ].map(a => (
            <button key={a.label} className="action-card" onClick={() => onNavigate(a.module)}>
              <span className="action-icon">{a.icon}</span>
              <span className="action-label">{a.label}</span>
              <span className="action-desc">{a.desc}</span>
              <span className="action-arrow">→</span>
            </button>
          ))}
        </div>
      </div>

      {/* Recent activity */}
      <div className="recent-section">
        <h2 className="section-title">Recent Activity</h2>
        <div className="activity-list">
          {[
            { time: '2h ago',  text: 'Navy blazer set tried on — saved to favourites', icon: '✂' },
            { time: '1d ago',  text: 'Order #TL-2041 dispatched for stitching',        icon: '📦' },
            { time: '3d ago',  text: 'Body scan updated — 3 measurements refined',     icon: '◎' },
          ].map((a, i) => (
            <div className="activity-item" key={i}>
              <span className="act-icon">{a.icon}</span>
              <div className="act-body">
                <span className="act-text">{a.text}</span>
                <span className="act-time">{a.time}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ── Saved Fits placeholder ─────────────────────────────────────── */
function SavedFitsModule() {
  const saved = [
    { id: 1, name: 'Navy Executive Set', date: 'Jun 12', color: '#1a3a5c' },
    { id: 2, name: 'Charcoal Business',  date: 'Jun 8',  color: '#3a3a3a' },
    { id: 3, name: 'Midnight Slim Fit',  date: 'May 30', color: '#0d1b2a' },
  ];

  return (
    <div className="module saved-module">
      <div className="module-header">
        <h1>Saved Fits</h1>
        <p>Your favourited blazer and tie combinations.</p>
      </div>
      <div className="saved-grid">
        {saved.map(item => (
          <div className="saved-card" key={item.id}>
            <div className="saved-preview" style={{ background: `linear-gradient(135deg, ${item.color}, #8b6914)` }}>
              <span className="saved-preview-icon">✂</span>
            </div>
            <div className="saved-info">
              <span className="saved-name">{item.name}</span>
              <span className="saved-date">Saved {item.date}</span>
            </div>
            <div className="saved-actions">
              <button className="btn-sm primary">Try Again</button>
              <button className="btn-sm ghost">Order</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── Orders placeholder ─────────────────────────────────────────── */
function OrdersModule() {
  const orders = [
    { id: 'TL-2041', status: 'Stitching',   progress: 60, set: 'Navy Executive Set' },
    { id: 'TL-1988', status: 'Dispatched',  progress: 90, set: 'Charcoal Business'  },
    { id: 'TL-1754', status: 'Delivered',   progress: 100, set: 'Midnight Slim Fit' },
  ];

  return (
    <div className="module orders-module">
      <div className="module-header">
        <h1>My Orders</h1>
        <p>Track your custom-stitched orders in real time.</p>
      </div>
      <div className="orders-list">
        {orders.map(o => (
          <div className="order-card" key={o.id}>
            <div className="order-top">
              <div>
                <span className="order-id">{o.id}</span>
                <span className="order-set">{o.set}</span>
              </div>
              <span className={`order-status status-${o.status.toLowerCase()}`}>{o.status}</span>
            </div>
            <div className="order-progress-bar">
              <div className="order-progress-fill" style={{ width: `${o.progress}%` }} />
            </div>
            <span className="order-pct">{o.progress}% complete</span>
          </div>
        ))}
      </div>
    </div>
  );
}


export default Dashboard;
