import React, { useState, useEffect, useRef } from 'react';
import {
  getAllPrototypes,
  addPrototype,
  updatePrototype,
  deletePrototype,
} from '../utils/PrototypeStore';
import '../styles/PrototypeManager.css';

/**
 * PrototypeManager.js  (v2 — file-system backed)
 *
 * Uploads images as real files to the Express server.
 * Images are saved to public/suit-prototypes/ and referenced
 * by a URL path (/suit-prototypes/filename.png), NOT Base64.
 * This means they are included in `npm run build` and survive deployments.
 */

const ACCEPTED = '.png,.jpg,.jpeg,.webp';

const emptyForm = () => ({
  name:        '',
  description: '',
  tags:        '',
  blazerColor: '#1a1a2e',
  tieColor:    '#c0392b',
  file:        null,      // File object
  previewUrl:  null,      // local object URL for preview before upload
});

function PrototypeManager() {
  const [prototypes,    setPrototypes]    = useState([]);
  const [loading,       setLoading]       = useState(true);
  const [error,         setError]         = useState(null);
  const [mode,          setMode]          = useState('list'); // 'list' | 'add' | 'edit'
  const [editTarget,    setEditTarget]    = useState(null);
  const [form,          setForm]          = useState(emptyForm());
  const [dragOver,      setDragOver]      = useState(false);
  const [saving,        setSaving]        = useState(false);
  const [saveError,     setSaveError]     = useState(null);
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  const [search,        setSearch]        = useState('');
  const [previewId,     setPreviewId]     = useState(null);
  const fileInputRef = useRef(null);

  /* ── Load prototypes from server on mount ─────────────────────── */
  const reload = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getAllPrototypes();
      setPrototypes(data);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { reload(); }, []);

  /* ── Clean up object URL on unmount / file change ─────────────── */
  useEffect(() => {
    return () => {
      if (form.previewUrl) URL.revokeObjectURL(form.previewUrl);
    };
  }, [form.previewUrl]);

  /* ── File selected ────────────────────────────────────────────── */
  const handleFile = (file) => {
    if (!file || !file.type.startsWith('image/')) return;
    // Revoke previous object URL
    if (form.previewUrl) URL.revokeObjectURL(form.previewUrl);
    const previewUrl = URL.createObjectURL(file);
    setForm(f => ({
      ...f,
      file,
      previewUrl,
      name: f.name || file.name.replace(/\.[^.]+$/, '').replace(/[-_]/g, ' '),
    }));
  };

  const onFileInput = (e) => { if (e.target.files[0]) handleFile(e.target.files[0]); };
  const onDrop      = (e) => {
    e.preventDefault(); setDragOver(false);
    if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
  };

  const handleField = (k, v) => setForm(f => ({ ...f, [k]: v }));

  /* ── Open add form ─────────────────────────────────────────────── */
  const openAdd = () => {
    setForm(emptyForm());
    setEditTarget(null);
    setSaveError(null);
    setMode('add');
  };

  /* ── Open edit form ────────────────────────────────────────────── */
  const openEdit = (proto) => {
    setForm({
      name:        proto.name,
      description: proto.description || '',
      tags:        (proto.tags || []).join(', '),
      blazerColor: proto.blazerColor || '#1a1a2e',
      tieColor:    proto.tieColor    || '#c0392b',
      file:        null,
      previewUrl:  null,
    });
    setEditTarget(proto);
    setSaveError(null);
    setMode('edit');
  };

  /* ── Save ──────────────────────────────────────────────────────── */
  const handleSave = async () => {
    setSaveError(null);
    if (!form.name.trim()) { setSaveError('Please enter a name.'); return; }
    if (mode === 'add' && !form.file) { setSaveError('Please select an image file.'); return; }

    setSaving(true);
    try {
      if (mode === 'add') {
        // Build FormData — image is a real File, not Base64
        const fd = new FormData();
        fd.append('image',       form.file);
        fd.append('name',        form.name.trim());
        fd.append('description', form.description.trim());
        fd.append('tags',        form.tags);
        fd.append('blazerColor', form.blazerColor);
        fd.append('tieColor',    form.tieColor);
        await addPrototype(fd);
      } else {
        // Edit: metadata only (image replacement not needed; add separately)
        await updatePrototype(editTarget.id, {
          name:        form.name.trim(),
          description: form.description.trim(),
          tags:        form.tags,
          blazerColor: form.blazerColor,
          tieColor:    form.tieColor,
        });
      }
      await reload();
      setMode('list');
    } catch (e) {
      setSaveError(e.message);
    } finally {
      setSaving(false);
    }
  };

  /* ── Delete ────────────────────────────────────────────────────── */
  const handleDelete = async (id) => {
    try {
      await deletePrototype(id);
      setDeleteConfirm(null);
      await reload();
    } catch (e) {
      alert(`Delete failed: ${e.message}`);
    }
  };

  /* ── Filter ────────────────────────────────────────────────────── */
  const filtered = prototypes.filter(p => {
    const q = search.toLowerCase();
    return (
      p.name.toLowerCase().includes(q) ||
      (p.description || '').toLowerCase().includes(q) ||
      (p.tags || []).some(t => t.toLowerCase().includes(q))
    );
  });

  /* ── Image src helper ──────────────────────────────────────────── */
  // In production imageUrl = /suit-prototypes/filename.png (static file)
  const imgSrc = (proto) => proto.imageUrl;

  /* ════════════════════════════════════════════════════════════
     LIST VIEW
  ════════════════════════════════════════════════════════════ */
  if (mode === 'list') {
    return (
      <div className="pm-root">
        <div className="pm-header">
          <div className="pm-title-row">
            <div>
              <h1 className="pm-title">Suit Prototypes</h1>
              <p className="pm-sub">
                Upload transparent PNG / JPG suit images. Files are saved to
                <code> public/suit-prototypes/</code> and included in every build.
              </p>
            </div>
            <button className="pm-add-btn" onClick={openAdd}>+ Upload New</button>
          </div>

          <div className="pm-toolbar">
            <div className="pm-search-wrap">
              <span className="pm-search-icon">🔍</span>
              <input
                className="pm-search"
                type="text"
                placeholder="Search by name, description or tag…"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
              {search && (
                <button className="pm-clear-search" onClick={() => setSearch('')}>✕</button>
              )}
            </div>
            <span className="pm-count">
              {filtered.length} / {prototypes.length} suit{prototypes.length !== 1 ? 's' : ''}
            </span>
          </div>
        </div>

        {/* Loading */}
        {loading && (
          <div className="pm-loading">
            <div className="pm-spinner" />
            <span>Loading prototypes…</span>
          </div>
        )}

        {/* Server error */}
        {error && !loading && (
          <div className="pm-error-box">
            <strong>⚠ Could not load prototypes</strong>
            <p>{error}</p>
            <p>Make sure the Express server is running: <code>node server/index.js</code></p>
            <button className="pm-ghost-btn" onClick={reload}>Retry</button>
          </div>
        )}

        {/* Empty state */}
        {!loading && !error && prototypes.length === 0 && (
          <div className="pm-empty">
            <span className="pm-empty-icon">👔</span>
            <h3>No suit prototypes yet</h3>
            <p>Upload your first transparent PNG or JPG to get started.</p>
            <button className="pm-add-btn" onClick={openAdd}>Upload First Prototype</button>
          </div>
        )}

        {/* No search results */}
        {!loading && !error && prototypes.length > 0 && filtered.length === 0 && (
          <div className="pm-empty">
            <span className="pm-empty-icon">🔍</span>
            <h3>No matches for "{search}"</h3>
            <button className="pm-ghost-btn" onClick={() => setSearch('')}>Clear search</button>
          </div>
        )}

        {/* Grid */}
        {!loading && !error && filtered.length > 0 && (
          <div className="pm-grid">
            {filtered.map(proto => (
              <div key={proto.id} className="pm-card">
                {/* Image preview */}
                <div
                  className="pm-card-img-wrap"
                  onClick={() => setPreviewId(proto.id)}
                  title="Click to preview"
                >
                  <div className="pm-checkerboard" />
                  <img
                    src={imgSrc(proto)}
                    alt={proto.name}
                    className="pm-card-img"
                  />
                  <div className="pm-card-overlay">
                    <span className="pm-card-zoom">🔍 Preview</span>
                  </div>
                </div>

                {/* Card body */}
                <div className="pm-card-body">
                  <div className="pm-card-top">
                    <span className="pm-card-name">{proto.name}</span>
                    <div className="pm-card-swatches">
                      <span className="pm-swatch" style={{ background: proto.blazerColor }} title="Blazer" />
                      <span className="pm-swatch" style={{ background: proto.tieColor }}    title="Tie"    />
                    </div>
                  </div>

                  {proto.description && (
                    <p className="pm-card-desc">{proto.description}</p>
                  )}

                  {proto.tags && proto.tags.length > 0 && (
                    <div className="pm-card-tags">
                      {proto.tags.map(t => <span key={t} className="pm-tag">{t}</span>)}
                    </div>
                  )}

                  {/* File path info */}
                  <div className="pm-file-path">
                    <span className="pm-file-path-icon">📁</span>
                    <code>public/suit-prototypes/{proto.fileName}</code>
                  </div>

                  <span className="pm-card-date">
                    {new Date(proto.uploadedAt).toLocaleDateString()}
                  </span>

                  <div className="pm-card-actions">
                    <button className="pm-btn pm-btn-edit" onClick={() => openEdit(proto)}>✏ Edit</button>
                    <button className="pm-btn pm-btn-del"  onClick={() => setDeleteConfirm(proto.id)}>🗑 Delete</button>
                  </div>
                </div>

                {/* Delete confirm overlay */}
                {deleteConfirm === proto.id && (
                  <div className="pm-del-confirm">
                    <p>Delete <strong>{proto.name}</strong>?<br/>
                      <small>The image file will also be removed from the server.</small>
                    </p>
                    <div className="pm-del-actions">
                      <button className="pm-btn pm-btn-del"   onClick={() => handleDelete(proto.id)}>Yes, delete</button>
                      <button className="pm-btn pm-btn-ghost" onClick={() => setDeleteConfirm(null)}>Cancel</button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Fullscreen preview */}
        {previewId && (() => {
          const p = prototypes.find(x => x.id === previewId);
          return p ? (
            <div className="pm-modal" onClick={() => setPreviewId(null)}>
              <div className="pm-modal-inner" onClick={e => e.stopPropagation()}>
                <button className="pm-modal-close" onClick={() => setPreviewId(null)}>✕</button>
                <div className="pm-modal-checker">
                  <img src={imgSrc(p)} alt={p.name} className="pm-modal-img" />
                </div>
                <div className="pm-modal-info">
                  <span className="pm-card-name">{p.name}</span>
                  {p.description && <p className="pm-card-desc">{p.description}</p>}
                  <code className="pm-modal-path">📁 public/suit-prototypes/{p.fileName}</code>
                  <div style={{ display:'flex', gap: 8, marginTop: 10 }}>
                    <button className="pm-btn pm-btn-edit" onClick={() => { setPreviewId(null); openEdit(p); }}>✏ Edit</button>
                  </div>
                </div>
              </div>
            </div>
          ) : null;
        })()}
      </div>
    );
  }

  /* ════════════════════════════════════════════════════════════
     ADD / EDIT FORM
  ════════════════════════════════════════════════════════════ */
  const previewSrc = form.previewUrl || (editTarget ? imgSrc(editTarget) : null);

  return (
    <div className="pm-root">
      <div className="pm-form-header">
        <button className="pm-back-btn" onClick={() => setMode('list')}>← Back</button>
        <h2 className="pm-form-title">
          {mode === 'add' ? 'Upload New Suit Prototype' : `Edit — ${editTarget?.name}`}
        </h2>
      </div>

      {saveError && (
        <div className="pm-save-error">⚠ {saveError}</div>
      )}

      <div className="pm-form-layout">
        {/* Left: image upload */}
        <div className="pm-upload-col">
          <label className="pm-upload-label">
            {mode === 'add' ? 'Suit Image *' : 'Replace Image (optional)'}
          </label>

          <div
            className={`pm-dropzone ${dragOver ? 'drag-over' : ''} ${previewSrc ? 'has-image' : ''}`}
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={onDrop}
            onClick={() => fileInputRef.current?.click()}
          >
            {previewSrc ? (
              <>
                <div className="pm-checker-bg" />
                <img src={previewSrc} alt="Preview" className="pm-upload-preview" />
                <div className="pm-upload-replace">Click or drop to replace</div>
              </>
            ) : (
              <div className="pm-upload-invite">
                <span className="pm-upload-icon">📂</span>
                <p className="pm-upload-text">
                  Drop PNG / JPG here<br/>
                  <span>or click to browse</span>
                </p>
                <p className="pm-upload-hint">
                  Transparent PNG works best for overlays.<br />
                  Saved to <code>public/suit-prototypes/</code>
                </p>
              </div>
            )}
          </div>

          <input
            ref={fileInputRef}
            type="file"
            accept={ACCEPTED}
            style={{ display: 'none' }}
            onChange={onFileInput}
          />

          {form.file && (
            <p className="pm-file-name">📎 {form.file.name} ({(form.file.size / 1024).toFixed(0)} KB)</p>
          )}
          {!form.file && editTarget && (
            <p className="pm-file-name">
              Current file: <code>public/suit-prototypes/{editTarget.fileName}</code>
            </p>
          )}

          <div className="pm-tip-box">
            <span>💡</span>
            <div>
              <strong>Build-safe storage:</strong> Images are saved as real files inside
              <code> public/suit-prototypes/</code>. Running <code>npm run build</code> copies
              them into the <code>build/</code> folder, so they survive every deployment.
            </div>
          </div>
        </div>

        {/* Right: metadata */}
        <div className="pm-fields-col">
          <div className="pm-field">
            <label className="pm-field-label">Name <span className="pm-req">*</span></label>
            <input
              className="pm-input"
              type="text"
              placeholder="e.g. Navy Double Breasted"
              value={form.name}
              onChange={e => handleField('name', e.target.value)}
            />
          </div>

          <div className="pm-field">
            <label className="pm-field-label">Description</label>
            <textarea
              className="pm-input pm-textarea"
              placeholder="e.g. Peak lapel, double breasted, Italian wool"
              value={form.description}
              onChange={e => handleField('description', e.target.value)}
              rows={3}
            />
          </div>

          <div className="pm-field">
            <label className="pm-field-label">
              Tags <span className="pm-hint-text">(comma separated)</span>
            </label>
            <input
              className="pm-input"
              type="text"
              placeholder="navy, peak lapel, double-breasted, formal"
              value={form.tags}
              onChange={e => handleField('tags', e.target.value)}
            />
          </div>

          <div className="pm-field-row">
            <div className="pm-field">
              <label className="pm-field-label">Blazer colour</label>
              <div className="pm-color-row">
                <input type="color" className="pm-color-pick" value={form.blazerColor} onChange={e => handleField('blazerColor', e.target.value)} />
                <input className="pm-input pm-color-hex" type="text" value={form.blazerColor} onChange={e => handleField('blazerColor', e.target.value)} />
              </div>
            </div>
            <div className="pm-field">
              <label className="pm-field-label">Tie colour</label>
              <div className="pm-color-row">
                <input type="color" className="pm-color-pick" value={form.tieColor} onChange={e => handleField('tieColor', e.target.value)} />
                <input className="pm-input pm-color-hex" type="text" value={form.tieColor} onChange={e => handleField('tieColor', e.target.value)} />
              </div>
            </div>
          </div>

          <div className="pm-swatch-preview">
            <span className="pm-swatch-big" style={{ background: form.blazerColor }} />
            <span className="pm-swatch-big" style={{ background: '#f8fafc', border: '1px solid #ccc' }} />
            <span className="pm-swatch-big" style={{ background: form.tieColor }} />
            <span className="pm-swatch-preview-label">Colour preview</span>
          </div>

          <div className="pm-form-actions">
            <button
              className="pm-save-btn"
              onClick={handleSave}
              disabled={saving || (mode === 'add' && !form.file) || !form.name.trim()}
            >
              {saving ? '⏳ Saving…' : mode === 'add' ? '✓ Upload & Save' : '✓ Update'}
            </button>
            <button className="pm-ghost-btn" onClick={() => setMode('list')}>Cancel</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default PrototypeManager;
